"""
Module: business_management.py
Contains 100 authentic questions each (34 Easy, 33 Medium, 33 Hard) for:
1. Project Management
2. Finance & Accounting
3. Human Resource Management
4. Procurement & GeM
5. Digital Governance
"""
from scripts.question_helpers import make_q

def get_project_management_questions():
    qs = []
    raw_easy = [('What are the five official Process Groups defined in the PMBOK Guide?', 'Initiating, Planning, Executing, Monitoring & Controlling, and Closing', ['Concept, Design, Testing, Deployment, and Maintenance', 'Ideation, Budgeting, Staffing, Delivery, and Review', 'Scoping, Scheduling, Sourcing, Launching, and Auditing'], 'The PMBOK Guide organizes project activities into five universal process groups from project inception to formal closure.'), ('What is the primary purpose of a Project Charter?', 'Formally authorizes the existence of a project and grants the project manager authority', ['Details the day-to-day task assignments of individual developers', 'Specifies the final line-item accounting receipts of the project', 'Serves as the legally binding vendor procurement contract'], 'A Project Charter is issued by the project sponsor to establish the project and authorize resources.'), ("In project management, what does the acronym 'WBS' stand for?", 'Work Breakdown Structure', ['Work Baseline System', 'Weighted Budget Schedule', 'Weekly Business Summary'], 'A Work Breakdown Structure is a hierarchical decomposition of the total scope of work to be carried out.'), ('What is the smallest, lowest-level deliverable unit in a Work Breakdown Structure (WBS)?', 'Work Package', ['Milestone', 'Activity block', 'Project summary phase'], 'The lowest level of the WBS decomposition is called a work package, which can be scheduled, cost-estimated, and monitored.'), ('What does a Milestone represent in a project schedule?', 'A significant point or event in a project with zero duration', ['A task that takes exactly one calendar month to finish', 'The final payment made to external sub-contractors', 'A high-risk work package that requires double staffing'], 'Milestones have zero duration and mark key achievements such as phase completion or deliverable approval.'), ('What visual horizontal bar chart is universally used to depict project schedules over time?', 'Gantt Chart', ['Pareto Chart', 'Scatter Diagram', 'Ishikawa Diagram'], 'Developed by Henry Gantt, Gantt charts visually illustrate project start dates, durations, and end dates against a calendar timeline.'), ('In the RACI responsibility assignment matrix, what do the letters R-A-C-I stand for?', 'Responsible, Accountable, Consulted, and Informed', ['Reported, Approved, Controlled, and Initiated', 'Reviewed, Assigned, Checked, and Inspected', 'Resource, Action, Constraint, and Impact'], 'RACI clarifies team roles: Responsible does work, Accountable owns outcome, Consulted gives input, Informed receives updates.'), ("In a RACI matrix, how many individuals should ideally be designated as 'Accountable' for any single task?", 'Exactly one individual', ['At least two co-leads', 'The entire project team', 'Zero (it belongs to the steering committee)'], 'Accountability cannot be shared; having exactly one accountable person ensures clear ownership and eliminates finger-pointing.'), ("What is 'Scope Creep' in project management?", 'The uncontrolled gradual expansion of project scope without adjustments to time, cost, and resources', ['The scheduled delivery of features ahead of deadline', 'The systematic reduction of features to cut project budgets', 'The migration of code between development servers'], 'Scope creep occurs when new requirements are added informally without formal change control or budget/schedule revisions.'), ("In Earned Value Management (EVM), what does 'PV' represent?", 'Planned Value (authorized budget assigned to scheduled work)', ['Past Value', 'Procured Volume', 'Profit Variance'], 'Planned Value (PV) is the approved budget assigned to work scheduled to be completed by a specific date.'), ("In Earned Value Management (EVM), what does 'EV' represent?", 'Earned Value (the measure of work performed expressed in terms of budget authorized)', ['Estimated Variance', 'Expected Volume', 'Enterprise Value'], 'Earned Value (EV) measures the actual value of work accomplished against the original planned budget.'), ("In Earned Value Management (EVM), what does 'AC' stand for?", 'Actual Cost (the realized cost incurred for the work performed)', ['Annual Capital', 'Allocated Credit', 'Audited Charges'], 'Actual Cost (AC) is the total cost incurred in completing work during a given time period.'), ('What is the formula to calculate Cost Variance (CV) in Earned Value Management?', 'CV = EV - AC', ['CV = PV - AC', 'CV = AC - EV', 'CV = EV / AC'], 'Cost Variance is the difference between Earned Value and Actual Cost; a positive CV indicates under-budget performance.'), ('What is the formula to calculate Schedule Variance (SV) in Earned Value Management?', 'SV = EV - PV', ['SV = PV - EV', 'SV = EV / PV', 'SV = AC - PV'], 'Schedule Variance is Earned Value minus Planned Value; positive SV means the project is ahead of schedule.'), ('What does a Cost Performance Index (CPI) greater than 1.0 (CPI > 1.0) indicate?', 'The project is currently performing under budget', ['The project is spending more money than budgeted', 'The project is running behind schedule', 'The project has run out of operating capital'], 'A CPI greater than 1.0 indicates that the project is earning more value than the actual costs incurred (under budget).'), ('What does a Schedule Performance Index (SPI) greater than 1.0 (SPI > 1.0) indicate?', 'The project is progressing faster than scheduled (ahead of schedule)', ['The project is falling behind schedule', 'The project is exceeding its budget limits', 'The project schedule has been cancelled'], 'An SPI above 1.0 means project work is proceeding at a faster rate than originally planned.'), ("What is the 'Critical Path' in a project network diagram?", 'The longest sequence of dependent activities that determines the shortest possible project duration', ['The sequence of activities with the highest financial budget', 'The set of non-essential activities that can be postponed indefinitely', 'The path containing only external third-party contractor tasks'], 'The Critical Path has zero total float; any delay in critical path activities directly delays the project completion date.'), ("What is 'Float' or 'Slack' time in a project schedule?", 'The amount of time an activity can be delayed without delaying the project completion date', ['The extra vacation days accumulated by team members', 'The time lost due to unexpected hardware system crashes', 'The time buffer between morning and afternoon meetings'], 'Float is the flexibility available to delay a task without impacting subsequent milestones or the project finish date.'), ('What is the total float of activities that lie on the Critical Path?', 'Zero (0)', ['Positive 10 days', 'Negative 5 days', 'Equal to the total project duration'], 'Critical path activities by definition have zero total float because any delay directly postpones project delivery.'), ('Which schedule compression technique adds extra resources to critical path activities to shorten duration?', 'Crashing', ['Fast-tracking', 'Resource leveling', 'Scope trimming'], 'Crashing injects additional labor, overtime, or equipment to critical tasks, typically increasing overall project cost.'), ('Which schedule compression technique performs sequential critical path activities in parallel?', 'Fast-tracking', ['Crashing', 'Resource smoothing', 'De-scoping'], 'Fast-tracking overlaps phases or tasks that were originally planned in sequence, which increases project rework risk.'), ("In Agile and Scrum methodologies, what is a 'Sprint'?", 'A time-boxed iteration (usually 1 to 4 weeks) during which a working product increment is created', ['A daily 5-minute meeting where developers report blockers', 'The emergency rush phase occurring right before project launch', 'A marathon coding hackathon conducted over a weekend'], 'A sprint is a fixed-length iteration in Scrum where the team delivers a potentially releasable product increment.'), ('In Scrum, who is primarily responsible for maximizing the business value of the product and managing the Product Backlog?', 'Product Owner', ['Scrum Master', 'Lead Software Architect', 'Project Sponsor'], 'The Product Owner prioritizes user stories in the product backlog to ensure the highest business value is delivered first.'), ('In Scrum, what is the primary role of the Scrum Master?', 'Serving as a servant-leader and coach who removes impediments for the team', ['Assigning daily tasks to individual developers', 'Setting the retail selling price of the software product', 'Conducting annual performance reviews of developers'], 'The Scrum Master facilitates ceremonies, shields the team from external distractions, and resolves blockers.'), ('What is the recommended maximum duration of the Daily Scrum (Daily Standup) meeting?', '15 minutes', ['45 minutes', '1 hour', '5 minutes'], 'Daily Scrum is strictly time-boxed to 15 minutes to synchronize activities and identify blockers without lengthy discussions.'), ('What are the three standard questions answered by team members during a Daily Scrum standup?', 'What I did yesterday, what I will do today, and what impediments are in my way', ['How much budget was spent, who made mistakes, and when will we launch', 'What the client emailed, how many lines of code were written, and coffee choices', 'What features are cancelled, who needs a vacation, and contract terms'], 'These three questions maintain transparency, align daily focus, and highlight impediments requiring Scrum Master help.'), ('What is an Ishikawa diagram commonly known as in root cause analysis?', 'Fishbone Diagram (or Cause-and-Effect Diagram)', ['Spider Web Diagram', 'Control Chart', 'Scatter Matrix'], 'Created by Kaoru Ishikawa, the fishbone diagram visualizes factors contributing to an defect or effect.'), ('What does the Pareto Principle (80/20 Rule) state in quality management?', 'Roughly 80% of project problems or defects originate from 20% of causes', ['80% of project budget must be spent on the first 20% of tasks', '80% of team members produce only 20% of the total output', 'Projects always run 80 days late and 20% over budget'], 'Pareto analysis helps project teams prioritize efforts by focusing on the vital few causes generating most defects.'), ('What tool is used to identify, analyze, monitor, and document risks throughout a project lifecycle?', 'Risk Register', ['Purchase Order', 'Statement of Work', 'Burndown Chart'], 'A Risk Register logs identified risks, potential impacts, probability ratings, risk owners, and planned responses.'), ('In Agile, what visual chart displays the amount of remaining work versus time in a sprint?', 'Burndown Chart', ['Gantt Chart', 'Run Chart', 'Kanban board'], 'A Sprint Burndown Chart plots remaining story points day by day, showing whether the team is on track to complete the sprint backlog.'), ("What Agile visual tool uses columns such as 'To Do', 'In Progress', and 'Done' to manage work-in-progress?", 'Kanban Board', ['WBS Tree', 'PERT Network', 'Fishbone Chart'], 'Kanban boards visualize workflows and apply Work In Progress (WIP) limits to eliminate bottlenecks and optimize flow.'), ("In project procurement, what does 'RFP' stand for?", 'Request for Proposal', ['Required Financial Payment', 'Realized Forecast Plan', 'Resource Funding Protocol'], 'An RFP is a formal procurement document inviting prospective vendors to submit proposals outlining how they will solve a project need.'), ("What is a 'Statement of Work' (SOW) in project procurement?", 'A narrative description of products, services, or results to be delivered by a vendor under contract', ['A weekly timesheet filled out by project employees', 'The financial balance sheet of the contractor', 'The formal certificate of project completion'], 'The SOW outlines specifications, deliverables, standards, and acceptance criteria required from an external supplier.'), ("What is the primary objective of a 'Lessons Learned' session conducted during project closing?", 'To document successes, failures, and recommendations to improve performance on future projects', ['To assign blame and penalize underperforming team members', 'To recalculate corporate income taxes for the past fiscal quarter', 'To audit personal expense reports of project managers'], 'Lessons learned capture organizational process assets, preserving valuable experiential knowledge for future initiatives.')]
    for q, ca, wa, exp in raw_easy:
        qs.append(make_q(q, ca, wa, "EASY", exp))
    raw_med = [('In PERT (Program Evaluation and Review Technique), what is the formula to calculate the Beta PERT Expected Duration (Te)?', 'Te = (Optimistic + 4 * Most Likely + Pessimistic) / 6', ['Te = (Optimistic + Most Likely + Pessimistic) / 3', 'Te = (Optimistic + 2 * Most Likely + Pessimistic) / 4', 'Te = (Optimistic + 6 * Most Likely + Pessimistic) / 8'], 'The Beta PERT distribution weights the most likely estimate by 4 to calculate a realistic weighted average duration.'), ('What is the formula to calculate the standard deviation (sigma) of an activity in PERT estimation?', 'Sigma = (Pessimistic - Optimistic) / 6', ['Sigma = (Pessimistic + Optimistic) / 2', 'Sigma = (Pessimistic - Most Likely) / 3', 'Sigma = (Most Likely - Optimistic) / 4'], 'The standard deviation measures estimation uncertainty, representing the spread across six standard deviations.'), ('If a project has an Earned Value (EV) of $80,000 and an Actual Cost (AC) of $100,000, what is the Cost Performance Index (CPI)?', '0.80', ['1.25', '0.20', '-$20,000'], 'CPI = EV / AC = 80,000 / 100,000 = 0.80, indicating the project is earning 80 cents of value for every dollar spent.'), ('If a project has an Earned Value (EV) of $90,000 and a Planned Value (PV) of $100,000, what is the Schedule Performance Index (SPI)?', '0.90', ['1.11', '-$10,000', '0.10'], 'SPI = EV / PV = 90,000 / 100,000 = 0.90, indicating the project is progressing at 90% of the planned schedule rate.'), ('In Earned Value Management, what is the formula to calculate Estimate at Completion (EAC) assuming future cost performance remains at current CPI?', 'EAC = BAC / CPI', ['EAC = BAC - EV', 'EAC = AC + (BAC - EV)', 'EAC = PV * CPI'], 'When current cost variances are expected to persist, EAC is calculated by dividing the Budget at Completion (BAC) by CPI.'), ("What is the difference between 'Free Float' and 'Total Float'?", 'Free Float delays an activity without delaying the immediate successor; Total Float without delaying project completion', ['Free Float applies to critical path; Total Float applies to non-critical path', 'Free Float involves cost savings; Total Float involves time extensions', 'Free Float is calculated by the client; Total Float is calculated by the team'], 'Total Float measures flexibility regarding the project finish date, whereas Free Float measures flexibility regarding successor start dates.'), ("What is the primary distinction between 'Resource Leveling' and 'Resource Smoothing'?", 'Resource Leveling can alter the critical path and project finish date; Resource Smoothing never alters the critical path', ['Resource Leveling reduces costs; Resource Smoothing increases staffing', 'Resource Leveling is only used in Agile; Resource Smoothing in Waterfall', 'Resource Leveling applies to equipment; Resource Smoothing applies to people'], 'Resource leveling resolves over-allocations by shifting dates (often extending duration), while smoothing operates within existing float.'), ("In project risk management, what is 'Expected Monetary Value' (EMV) calculated as?", 'EMV = Probability of Risk Event * Monetary Impact of Risk Event', ['EMV = Total Project Budget / Number of Identified Risks', 'EMV = Actual Cost - Planned Value', 'EMV = Highest Possible Loss + Lowest Possible Gain'], 'EMV is a statistical technique multiplying probability by dollar impact to quantify financial risk exposure.'), ('Which risk response strategy involves paying an external third party to take on the financial consequences of a threat?', 'Risk Transference (e.g., purchasing insurance or performance bonds)', ['Risk Mitigation', 'Risk Avoidance', 'Risk Acceptance'], 'Transference shifts liability or financial impact to a third party through insurance, warranties, guarantees, or contracts.'), ('What risk response strategy is being used when a project team redesigns a system to completely eliminate a hazardous chemical?', 'Risk Avoidance', ['Risk Acceptance', 'Risk Transference', 'Risk Mitigation'], 'Risk avoidance changes the project management plan to completely eradicate the condition that gives rise to the risk.'), ("What is the difference between a 'Contingency Reserve' and a 'Management Reserve'?", "Contingency Reserve is for 'known unknowns' managed by PM; Management Reserve is for 'unknown unknowns' managed by sponsor", ['Contingency Reserve is money; Management Reserve is extra calendar days', 'Contingency Reserve is for vendor bonuses; Management Reserve is for payroll', 'Contingency Reserve is part of scope; Management Reserve is outside scope'], 'Contingency reserves address identified risks in the risk register; management reserves address unforeseen events requiring scope change.'), ('In Scrum, what ceremony is held at the end of a sprint for the team to inspect their process and identify continuous improvements?', 'Sprint Retrospective', ['Sprint Review (Demo)', 'Sprint Planning', 'Daily Scrum'], 'Sprint Retrospective is dedicated to internal team process evaluation (what went well, what can be improved, action items).'), ("What is the primary difference between a 'Sprint Review' and a 'Sprint Retrospective' in Scrum?", 'Sprint Review demonstrates the product increment to stakeholders; Sprint Retrospective focuses on internal team process improvement', ['Sprint Review discusses team salaries; Sprint Retrospective discusses client invoices', 'Sprint Review plans the next sprint backlog; Sprint Retrospective writes test scripts', 'Sprint Review occurs daily; Sprint Retrospective occurs once a year'], 'The Review inspects the deliverable with stakeholders; the Retrospective inspects team teamwork, tools, and process internally.'), ("In Scrum, what does the 'Definition of Done' (DoD) signify?", 'An agreed checklist of technical criteria that must be satisfied before a user story can be considered complete', ['The final date when the software contract expires', 'The moment when the product manager accepts the initial budget', 'The point when the team has written 100% of code comments'], 'DoD ensures quality standards (e.g., code reviewed, unit tested, documentation updated, integrated into main branch).'), ("What does 'Velocity' measure in Agile project management?", 'The average number of story points completed and accepted by the team per sprint', ['The typing speed of software engineers in lines of code per hour', 'The turnaround time of customer support tickets', 'The speed at which the project manager approves expense claims'], 'Velocity tracks historical team delivery capacity across sprints, aiding realistic future sprint and release forecasting.'), ('What estimation technique uses Fibonacci sequence cards (1, 2, 3, 5, 8, 13) to collaboratively estimate relative effort?', 'Planning Poker', ['Wideband Delphi', 'Parametric Estimating', 'Analogous Estimating'], 'Planning Poker leverages gamified consensus to estimate user story complexity while preventing individual anchoring bias.'), ("In project quality management, what is the primary distinction between 'Quality Assurance' (QA) and 'Quality Control' (QC)?", 'QA is process-oriented (preventing defects); QC is product-oriented (detecting defects in finished deliverables)', ['QA is performed by developers; QC is performed by the marketing team', 'QA tests software hardware; QC audits financial accounting balances', 'QA occurs after release; QC occurs before development starts'], 'QA establishes robust processes and audits to build quality in; QC inspects deliverables to catch defects before delivery.'), ('In Statistical Process Control, what do Upper and Lower Control Limits (UCL and LCL) represent on a Control Chart?', 'Statistically determined thresholds (typically +/- 3 sigma) representing the boundaries of normal process variation', ['The maximum and minimum budget allowable for a task', 'The client-specified design tolerance limits in the contract', 'The daily working hours of testing personnel'], 'Control limits indicate whether a process is stable and in statistical control, based on natural process capability.'), ("In Tuckman's model of team development, what is the 'Storming' phase characterized by?", 'Conflict, competition, and friction as team members confront differing ideas and challenge authority', ['Polite introductions and exploratory social conversations', 'High performance where tasks are accomplished seamlessly', 'Establishment of mutual trust and collaborative team norms'], 'Storming is the turbulent second stage where personal boundaries and leadership dynamics are contested before norms form.'), ("In Tuckman's model of team development, what occurs during the 'Norming' stage?", 'Team members resolve differences, establish shared working agreements, and develop mutual trust', ['The team disbands following project completion', 'Severe interpersonal conflicts cause team dissolution', 'The team starts from scratch with new requirements'], 'During Norming, roles settle, collaboration deepens, and team cohesion stabilizes around shared operating rules.'), ('Which type of contract places the highest financial risk on the seller (contractor)?', 'Firm Fixed Price (FFP)', ['Cost Plus Fixed Fee (CPFF)', 'Time and Materials (T&M)', 'Cost Plus Percentage of Cost (CPPC)'], 'In FFP contracts, the seller is legally obligated to deliver the scope for an agreed sum; any cost overrun reduces seller profit.'), ('Which contract type places the highest cost risk on the buyer (customer)?', 'Cost Reimbursable (such as Cost Plus Percentage of Cost)', ['Firm Fixed Price (FFP)', 'Fixed Price with Economic Price Adjustment', 'Fixed Price Incentive Fee'], 'Cost reimbursable contracts obligate the buyer to pay all incurred vendor costs, creating minimal incentive for vendor cost control.'), ("What is 'Parametric Estimating' in project management?", 'An estimation technique that uses statistical relationships between historical data and variables (e.g., cost per square foot)', ['Estimating by asking three executive stakeholders for intuition', 'Comparing the current project to one previous identical project', 'Breaking tasks down to the minute work package level'], 'Parametric estimating calculates cost or duration by multiplying project metrics (e.g., number of cables, square meters) by unit rates.'), ("What is 'Analogous Estimating' (Top-Down Estimating)?", 'Estimating cost or duration using historical values from previous similar projects as a basis', ['Using mathematical algorithms and computer simulations', 'Conducting a formal tender among external contractors', 'Adding together individual bottom-up work packages'], 'Analogous estimation is quick and inexpensive, utilized in early stages when detailed project information is limited.'), ("In project schedule network diagrams, what is a 'Lead'?", 'The amount of time a successor activity can be advanced with respect to a predecessor activity', ['The delay required between two sequential activities', 'The senior engineer responsible for code deployment', 'The slack time remaining before the project finish date'], 'A lead is an acceleration of the successor task (e.g., starting wallpapering 2 days before painting finishes).'), ("In project schedule network diagrams, what is a 'Lag'?", 'A directed delay inserted between a predecessor and successor activity (e.g., waiting for concrete to cure)', ['An accidental scheduling mistake made by project planners', 'The negative variance on an Earned Value chart', 'The acceleration of a task ahead of its planned start'], 'A lag forces a waiting period between dependent tasks, such as allowing 3 days for paint drying before plastering.'), ("What is the primary role of a 'Change Control Board' (CCB)?", 'A formally constituted group responsible for reviewing, evaluating, approving, or rejecting proposed project changes', ['A labor union committee handling employee workplace grievances', 'The corporate board of directors auditing annual dividends', 'The IT department that resets employee network passwords'], 'The CCB ensures that no change to baseline scope, cost, or schedule occurs without rigorous evaluation and stakeholder impact review.'), ("In stakeholder management, what does a 'Power/Interest Grid' help project managers determine?", 'The appropriate communication and engagement strategy for different stakeholder groups', ['The exact bonus pay distribution among executives', 'The technical architecture of the underlying cloud databases', 'The sequence of critical path tasks in project networks'], 'Stakeholders with high power and high interest are managed closely, whereas low power and low interest receive minimal monitoring.'), ('What does a To-Complete Performance Index (TCPI) of 1.25 signify?', 'The remaining project work must achieve a cost efficiency of 125% to finish within the approved budget', ['The project is 25% ahead of the original baseline schedule', 'The team will finish the project with a 25% surplus budget', 'The project manager should immediately cancel 25% of scope'], 'TCPI > 1.0 means future work must be performed with higher efficiency than originally planned to meet the target budget.'), ("In configuration management, what is a 'Baseline'?", 'The approved version of a work product (scope, cost, schedule) that can only be changed through formal change control', ['The worst-case financial performance scenario', 'The minimum qualification required for hiring project staff', 'The lowest grade of materials allowed by safety regulations'], 'Baselines (Scope Baseline, Cost Baseline, Schedule Baseline) serve as the standard comparison points for performance measurement.'), ("What is 'Gold Plating' in project scope management?", 'Giving the customer extra features or higher quality than agreed upon without formal approval', ['Applying real gold leafing to product exterior packaging', 'Delivering a luxury hardware version to corporate sponsors', 'Achieving zero defects across all software modules'], 'Gold plating introduces unnecessary risk, unauthorized costs, and potential defects; professional PM principles advise against it.'), ("What is a 'Secondary Risk' in project risk management?", 'A new risk that arises as a direct consequence of implementing a risk response', ['A risk of negligible financial consequence', 'A risk that only affects internal junior team members', 'A risk that occurs after the project warranty period ends'], 'Secondary risks must be analyzed during risk response planning (e.g., installing a backup generator introduces fuel storage fire risk).'), ("What is a 'Residual Risk' in risk management?", 'The risk that remains after risk response strategies have been implemented', ['A risk that has completely disappeared from the project', 'The risk incurred by sub-contractors after project handover', 'A risk that occurred in the previous fiscal year'], 'Residual risks are acknowledged and accepted; project teams maintain contingency reserves to absorb residual risk impacts.')]
    for q, ca, wa, exp in raw_med:
        qs.append(make_q(q, ca, wa, "MEDIUM", exp))
    raw_hard = [('In Earned Value Management, what is the formula to calculate Variance at Completion (VAC)?', 'VAC = BAC - EAC', ['VAC = EAC - BAC', 'VAC = AC - EV', 'VAC = PV - AC'], 'Variance at Completion is the difference between Budget at Completion and Estimate at Completion; positive VAC means favorable.'), ('If BAC = $200,000, EV = $100,000, AC = $120,000, and PV = $110,000, what is the TCPI to achieve the original BAC?', '1.25', ['0.83', '1.00', '1.10'], 'TCPI_BAC = (BAC - EV) / (BAC - AC) = (200,000 - 100,000) / (200,000 - 120,000) = 100,000 / 80,000 = 1.25.'), ('When calculating EAC under the assumption that both CPI and SPI influence future work, what is the correct formula?', 'EAC = AC + [(BAC - EV) / (CPI * SPI)]', ['EAC = BAC / (CPI + SPI)', 'EAC = AC + (BAC - PV)', 'EAC = (BAC - EV) / (CPI - SPI)'], 'This composite formula adjusts the remaining work by both cost efficiency (CPI) and schedule efficiency (SPI), reflecting combined pressure.'), ("In project schedule analysis, what condition results in a 'Negative Float' on a network diagram?", 'When a fixed contractual completion deadline is earlier than the calculated early finish date of the critical path', ['When project activities finish earlier than planned', 'When resources work without taking scheduled lunch breaks', 'When total budget exceeds earned value by more than 10%'], 'Negative float indicates that the project is mathematically in violation of an imposed constraint date, requiring urgent schedule compression.'), ('In Earned Schedule (ES) theory, how is Earned Schedule calculated from the Earned Value and Planned Value curves?', 'By determining the point in time where the current Earned Value equals the Planned Value curve', ['By multiplying the actual calendar days by the CPI index', 'By dividing the critical path duration by total team velocity', 'By taking the derivative of cumulative Actual Cost'], 'Earned Schedule extends EVM to time units, preventing the mathematical flaw where SPI converges to 1.0 at project completion regardless of lateness.'), ('What is the primary formula for Schedule Performance Index based on time (SPI_t) in Earned Schedule management?', 'SPI_t = ES / AT (where ES is Earned Schedule and AT is Actual Time)', ['SPI_t = AT / ES', 'SPI_t = (ES - AT) / BAC', 'SPI_t = EV / AC'], 'SPI_t accurately measures time-based schedule efficiency without collapsing back to 1.0 when a project finishes late.'), ('In project risk analysis, what does a Monte Carlo simulation generate?', 'A cumulative probability distribution of project completion dates and total costs through thousands of iterations', ['A single deterministic schedule date with 100% guarantee', 'The exact list of contractor personnel who will commit errors', 'A deterministic Gantt chart with fixed float values'], 'Monte Carlo randomly samples probability distributions for each task to calculate the likelihood of meeting specific cost/time targets.'), ("In a project network diagram, what is 'Path Convergence' and why does it represent significant risk?", 'Multiple predecessor activities merge into a single successor; the successor is delayed if ANY predecessor is delayed', ['Two critical paths run parallel without ever meeting', 'A single task splits into multiple independent threads', 'Activities share the same geographic physical work site'], 'Path convergence magnifies risk because the probability of on-time start for the successor is the product of all predecessor probabilities.'), ("In Critical Chain Project Management (CCPM), what is the 'Project Buffer'?", 'A consolidated contingency buffer placed at the very end of the critical chain to protect the final delivery date', ['Extra money added to individual department line items', 'A waiting room built for project stakeholders during reviews', 'A five-day holiday granted to developers after every sprint'], 'CCPM strips safety margins from individual tasks and aggregates them into strategic project and feeding buffers.'), ("In Critical Chain Project Management (CCPM), where are 'Feeding Buffers' positioned?", 'At points where non-critical chains merge into the critical chain', ['Directly after the kickoff meeting', 'At the very end of the project lifecycle', 'Inside the executive management contingency reserve'], 'Feeding buffers protect the critical chain from delays occurring on feeder (non-critical) paths.'), ("In quality management, what is the defect rate corresponding to a 'Six Sigma' process capability (accounting for 1.5 sigma drift)?", '3.4 defects per million opportunities (DPMO)', ['6.0 defects per thousand parts', '66,807 defects per million opportunities', '0.0001 defects per billion opportunities'], 'A Six Sigma quality process yields 99.99966% defect-free output, translating mathematically to 3.4 DPMO with standard 1.5 sigma shift.'), ("What does the 'Taguchi Loss Function' postulate regarding quality and customer satisfaction?", 'Financial loss to society begins whenever a product parameter deviates from target, even within tolerance limits', ['Loss only occurs when a product is completely rejected at inspection', 'Quality improves linearly with the amount of money spent on marketing', 'Zero defects guarantees 100% profitability in competitive markets'], 'Genichi Taguchi showed that customer dissatisfaction increases quadratically as characteristics drift from the nominal target value.'), ("In project procurement, what is the 'Point of Total Assumption' (PTA) in a Fixed Price Incentive Fee (FPIF) contract?", 'The cost point beyond which the contractor assumes 100% of all additional cost overruns dollar-for-dollar', ['The moment when the buyer pays the final invoice', 'The point where the contractor achieves maximum incentive bonus', 'The initial cost estimate agreed at contract signature'], 'PTA = [(Ceiling Price - Target Price) / Buyer Share Ratio] + Target Cost. Beyond PTA, the contractor bears all overrun burden.'), ('In an FPIF contract with Target Cost = $100k, Target Fee = $10k, Ceiling Price = $120k, Buyer Share = 80%, what is the PTA?', '$112,500', ['$120,000', '$110,000', '$105,000'], 'PTA = Target Cost + (Ceiling Price - Target Price) / Buyer Share = 100,000 + (120,000 - 110,000) / 0.80 = 100,000 + 12,500 = $112,500.'), ('Under the Law of Diminishing Returns in project resource management:', 'Adding more resources beyond optimal capacity yields progressively smaller increases in output', ['Adding staff to a late project makes it finish early', 'Project costs decrease exponentially as team size doubles', 'Overtime work produces identical productivity as normal hours'], 'Excessive staffing increases communication overhead, coordination complexity, and interference, reducing marginal productivity.'), ("What does 'Brooks' Law' famously state regarding software project staffing?", "'Adding manpower to a late software project makes it later'", ["'Doubling developers halves project schedule duration'", "'No software project can ever finish under original budget'", "'Quality increases proportionally to the number of testers'"], "Coined by Fred Brooks in 'The Mythical Man-Month', ramp-up communication overhead and training drain existing productivity."), ('In the Vroom-Yetton-Jago Decision Model, a project leader selects a decision-making style based on:', 'A decision tree evaluating decision quality, commitment requirements, problem structure, and team goal congruence', ['The Myers-Briggs personality profiles of team members', 'The current CPI and SPI metrics from Earned Value reports', 'The personal seniority rank of the project manager'], 'The model prescribes whether a leader should decide autocratically, consultatively, or facilitate consensus based on diagnostic questions.'), ("What is 'Cynefin Framework' used for in executive project leadership and decision-making?", 'Categorizing problems into Clear, Complicated, Complex, and Chaotic contexts to adopt appropriate responses', ['Calculating statistical variance in three-point cost estimates', 'Measuring database throughput in transaction processing systems', 'Auditing vendor invoices against contractual milestone triggers'], 'Developed by Dave Snowden, Cynefin guides whether to Sense-Categorize-Respond, Sense-Analyze, Sense-Probe, or Act immediately.'), ("In Agile scaling frameworks such as SAFe (Scaled Agile Framework), what is a 'Program Increment' (PI)?", 'A timeboxed planning cycle (typically 8 to 12 weeks) where an entire Agile Release Train plans and delivers value', ['The promotion of an individual developer to scrum master', 'The release of a minor security patch to staging servers', 'A weekly sprint conducted by senior management'], 'A PI aligns multiple Agile teams working together on an Agile Release Train (ART) via common cadence and PI Planning.'), ("What is the primary role of the 'Release Train Engineer' (RTE) in the Scaled Agile Framework (SAFe)?", 'Serving as the chief scrum master who facilitates ART events and drives program-level continuous improvement', ['Writing code for backend microservices pipelines', 'Deciding the annual marketing spend for enterprise products', 'Signing commercial vendor contracts with hardware suppliers'], 'The RTE acts as a servant leader facilitating PI execution, escalating impediments, and managing ART risks.'), ("In Scrum, how is the 'Sprint Goal' formally utilized by the Scrum Team?", 'As a single overarching objective set during Sprint Planning that guides team decisions throughout the sprint', ['As a fixed legal quota that results in salary deductions if missed', 'As an optional guideline created by external marketing executives', 'As a marketing slogan printed on office promotional posters'], 'The Sprint Goal provides coherence and focus, encouraging teamwork rather than disjointed individual user story work.'), ("What is the 'Kano Model' in project product management?", 'A customer satisfaction model categorizing features into Must-be, Performance, Attractive, and Indifferent', ['A statistical tool for predicting server downtime under peak load', 'A contract drafting framework for international marine shipping', 'A project scheduling algorithm that calculates free float'], 'Noriaki Kano mapped how feature presence versus customer satisfaction distinguishes baseline expectations from delighters.'), ("In organizational design, how does a 'Strong Matrix' organization differ from a 'Weak Matrix'?", 'Project Managers have primary authority over budget and resources in Strong Matrix; Functional Managers dominate in Weak Matrix', ['Strong Matrix has zero full-time project managers', 'Weak Matrix assigns all project decisions to external clients', 'Strong Matrix is only permitted in public sector government bodies'], 'In a strong matrix, dedicated PMs hold substantial authority, whereas in weak matrix, functional heads manage projects via coordinators.'), ("What is a 'Project Management Office' (PMO) designated as 'Directive' characterized by?", 'It directly manages projects, assigns project managers, and holds high degree of project control', ['It provides optional templates and acts purely as a consultative resource', 'It only audits tax returns at the end of the corporate fiscal year', 'It is an external consulting firm hired for one single audit'], 'PMO models range from Supportive (low control) and Controlling (moderate compliance) to Directive (direct command and management).'), ("In Agile frameworks, what is the 'Weighted Shortest Job First' (WSJF) prioritization metric based on?", 'Cost of Delay (CoD) divided by Job Duration or Size', ['Total Estimated Revenue divided by Developer Salaries', 'Risk Probability multiplied by Financial Monetary Impact', 'Customer Seniority Level divided by Sprint Length'], 'WSJF optimizes economic value flow by prioritizing high-value, high-urgency, short-duration backlog initiatives first.'), ('In Earned Value Management, if CV is positive and SV is negative, what does this indicate about project status?', 'The project is currently under budget but behind schedule', ['The project is over budget and ahead of schedule', 'The project is over budget and behind schedule', 'The project is performing exactly as planned'], 'CV = EV - AC > 0 means costs are lower than value earned (under budget); SV = EV - PV < 0 means behind schedule.'), ("What is 'Fast Tracking' rework risk primarily attributed to?", 'Prematurely starting subsequent activities before their predecessor designs or prerequisites are validated', ['Assigning too many junior engineers to high-complexity coding tasks', 'Exceeding the statutory working hours permitted by labor laws', 'Paying vendors earlier than required by contractual milestones'], 'Fast-tracking introduces rework because unforeseen changes in the predecessor task may invalidate progress on overlapping successor work.'), ("In project risk management, what is a 'Risk Breakdown Structure' (RBS)?", 'A hierarchical depiction of potential project risks organized by risk category and sub-category', ['A financial spreadsheet detailing money lost to workplace accidents', 'A breakdown of contractor penalty fees for delayed deliveries', 'A chronological timeline of project bugs logged in Jira'], 'An RBS organizes risks hierarchically (Technical, External, Organizational, Project Management) to aid comprehensive identification.'), ("What is the primary function of a 'Tornado Diagram' in quantitative project risk analysis?", 'A sensitivity analysis display that ranks variables by their relative impact on a project outcome', ['A weather forecast chart tracking tropical hurricane paths', 'A scatter plot showing developer productivity versus room temperature', 'A cumulative distribution curve of total project capital expend'], 'Tornado diagrams visually rank high-impact sensitivity variables at the top and low-impact at the bottom, resembling a tornado funnel.'), ("What is 'Benefit-Cost Ratio' (BCR) and when is an investment financially attractive?", 'BCR = Present Value of Benefits / Present Value of Costs; project is attractive when BCR > 1.0', ['BCR = Total Incurred Costs / Net Profit; project is attractive when BCR < 0.5', 'BCR = Revenue - Cost; project is attractive when BCR = 0', 'BCR = Depreciation Rate / Inflation Rate; attractive when BCR > 2.0'], 'A BCR greater than 1.0 indicates that the financial present value of benefits exceeds the present value of investment costs.'), ("In project financial appraisal, what does 'Internal Rate of Return' (IRR) represent?", 'The discount rate at which the Net Present Value (NPV) of all project cash flows equals zero', ['The annual rate of interest charged by commercial lending banks', 'The statutory corporate tax percentage payable on project profits', 'The inflation adjustment applied to employee annual bonuses'], "A project is viable if its IRR exceeds the organization's required hurdle rate or cost of capital."), ("In project scheduling, what is the 'Dangler' flaw in network logic?", 'An activity that has no predecessor or no successor, leaving an open-ended loop in the network', ['A resource assigned to three full-time projects simultaneously', 'A milestone that has a non-zero financial expenditure', 'A critical path that passes through a third-party vendor task'], 'Danglers break schedule calculations by preventing forward and backward passes from calculating true floats.'), ("What is 'Murphy's Law' as applied to project risk planning?", "'Anything that can go wrong will go wrong'", ["'Work expands to fill the time available for its completion'", "'Nine women cannot make a baby in one month'", "'Adding staff to a late project makes it later'"], "Murphy's Law reminds project managers to design resilient systems, incorporate contingency buffers, and plan defensive mitigations.")]
    for q, ca, wa, exp in raw_hard:
        qs.append(make_q(q, ca, wa, "HARD", exp))
    return qs

def get_finance_accounting_questions():
    qs = []
    raw_easy = [('What is the fundamental accounting equation?', "Assets = Liabilities + Owner's Equity", ["Assets = Liabilities - Owner's Equity", "Owner's Equity = Assets + Liabilities", "Liabilities = Assets + Owner's Equity"], 'The double-entry balance sheet equation requires total economic resources (Assets) to equal creditor claims (Liabilities) plus owner claims (Equity).'), ('Which accounting principle states that revenue must be recognized when earned, regardless of when cash is received?', 'Accrual Principle', ['Cash Principle', 'Conservatism Principle', 'Cost Principle'], 'Under accrual accounting, revenues and expenses are recorded in the period they occur, not when cash changes hands.'), ("Which financial statement reports a company's financial position at a specific point in time?", 'Balance Sheet (Statement of Financial Position)', ['Income Statement (P&L)', 'Cash Flow Statement', 'Statement of Retained Earnings'], 'A balance sheet presents a snapshot of assets, liabilities, and equity on a specific date (e.g., March 31).'), ("Which financial statement reports an enterprise's revenues, expenses, and net profit over a period of time?", 'Income Statement (Profit & Loss Statement)', ['Balance Sheet', 'Trial Balance', 'Bank Reconciliation Statement'], 'The income statement summarizes operating and non-operating financial performance over an accounting period.'), ('In double-entry bookkeeping, what does a debit entry signify for an asset account?', 'An increase in the asset', ['A decrease in the asset', 'No change to the asset', 'A transfer to equity'], 'In standard debit/credit rules, debits increase assets and expenses, while credits increase liabilities, equity, and revenues.'), ('In double-entry bookkeeping, what does a credit entry signify for a liability account?', 'An increase in the liability', ['A decrease in the liability', 'An asset write-off', 'A depreciation charge'], 'Liabilities carry a normal credit balance; hence, crediting a liability account increases its balance.'), ('What is the primary document used to record financial transactions in chronological order for the first time?', 'Journal', ['General Ledger', 'Trial Balance', 'Balance Sheet'], 'The journal is the book of original entry where financial events are first recorded in chronological sequence.'), ('What accounting book contains all individual accounts categorized by Assets, Liabilities, Equity, Revenues, and Expenses?', 'General Ledger', ['Day Book', 'Petty Cash Book', 'Inventory Register'], 'The ledger is the principal book containing permanent accounts to which journal transactions are posted.'), ('What is a Trial Balance used for?', 'To verify that total debits equal total credits across all ledger accounts', ['To calculate corporate income tax owed to government', 'To determine customer credit ratings', 'To audit physical inventory in warehouse'], 'A trial balance compiles ending debit and credit balances to check mathematical equality before preparing financial statements.'), ('What accounting concept assumes that an enterprise will continue operating into the foreseeable future?', 'Going Concern Concept', ['Entity Concept', 'Periodicity Concept', 'Money Measurement Concept'], 'The going concern assumption justifies carrying fixed assets at historical cost less depreciation rather than liquidation value.'), ('What accounting concept requires personal affairs of the owner to be kept separate from business transactions?', 'Business Entity Concept', ['Prudence Concept', 'Full Disclosure Concept', 'Materiality Concept'], 'The business entity concept dictates that a firm is an independent legal and economic entity distinct from its proprietors.'), ("What does the 'Matching Principle' in accounting dictate?", 'Expenses incurred to generate revenue must be recognized in the same period as that revenue', ['Debits must always match credits in each transaction', 'Physical inventory must match invoice quantities', 'Employee salaries must equal annual corporate profit'], 'Matching associates cause-and-effect expenses directly with related revenues to depict true periodic earnings.'), ('Which accounting method recognizes revenue and expenses only when physical money is received or paid out?', 'Cash Accounting', ['Accrual Accounting', 'Inflation Accounting', 'Mark-to-Market Accounting'], 'Cash basis accounting records cash receipts and disbursements, commonly used by individuals and small sole proprietors.'), ("What is 'Depreciation' in accounting?", 'The systematic allocation of the depreciable amount of a tangible fixed asset over its useful life', ['The sudden drop in market price of listed stocks', 'The decrease in foreign currency exchange rates', 'The annual interest paid on corporate debentures'], 'Depreciation accounts for physical wear and tear, technological obsolescence, and time decay of capital plant assets.'), ('What formula is used to calculate annual depreciation under the Straight-Line Method (SLM)?', 'Annual Depreciation = (Cost of Asset - Salvage Value) / Useful Life (in years)', ['Annual Depreciation = Cost of Asset * Useful Life', 'Annual Depreciation = (Cost + Salvage Value) / 2', 'Annual Depreciation = Salvage Value / Useful Life'], 'SLM distributes the net depreciable cost of an asset in equal annual amounts across its estimated productive lifespan.'), ("What are 'Current Assets' on a corporate balance sheet?", 'Assets expected to be converted into cash, sold, or consumed within one operating year', ['Assets held permanently for factory manufacturing', 'Intangible brand names and intellectual patents', 'Long-term bond investments maturing in 20 years'], 'Current assets include cash, marketable securities, trade receivables, and inventory expected to cycle within 12 months.'), ("What are 'Current Liabilities'?", 'Obligations due to be settled within one year or normal operating cycle', ['Long-term 30-year bank mortgages', 'Paid-up equity share capital', 'Deferred tax assets'], 'Current liabilities encompass trade payables, short-term commercial borrowings, accrued wages, and tax provisions due within a year.'), ('What is the formula to calculate Working Capital (Net Working Capital)?', 'Working Capital = Current Assets - Current Liabilities', ['Working Capital = Total Assets - Total Liabilities', 'Working Capital = Current Assets + Current Liabilities', 'Working Capital = Fixed Assets - Long-term Debt'], 'Net Working Capital measures short-term liquidity and operational buffer required to fund day-to-day trade activities.'), ('What is the formula for the Current Ratio?', 'Current Ratio = Current Assets / Current Liabilities', ['Current Ratio = Quick Assets / Current Liabilities', 'Current Ratio = Current Liabilities / Current Assets', 'Current Ratio = Cash / Total Liabilities'], 'Current ratio evaluates the capability of an enterprise to pay off its short-term obligations using short-term assets.'), ('What is the ideal or standard benchmark Current Ratio traditionally recommended for trading firms?', '2.0 : 1 (or 2:1)', ['1.0 : 1', '0.5 : 1', '5.0 : 1'], 'A 2:1 ratio provides a 100% safety buffer of current assets over current liabilities to absorb inventory valuation fluctuations.'), ("How does the 'Quick Ratio' (Acid-Test Ratio) differ from the Current Ratio?", 'Quick Ratio excludes Inventory and Prepaid Expenses from Current Assets', ['Quick Ratio excludes Cash and Bank balances', 'Quick Ratio includes long-term plant and machinery', 'Quick Ratio divides assets by total equity capital'], 'Inventory and prepaid expenses are excluded because they cannot be liquidated immediately into cash without price discounts.'), ("What does 'Gross Profit' represent on an income statement?", 'Sales Revenue minus Cost of Goods Sold (COGS)', ['Net Profit minus Operating Expenses', 'Sales Revenue minus Income Taxes', 'Operating Profit plus Depreciation Charges'], 'Gross profit indicates how efficiently a business produces or sources goods before subtracting administrative and marketing overheads.'), ('What is Cost of Goods Sold (COGS) calculated as?', 'COGS = Opening Stock + Net Purchases + Direct Costs - Closing Stock', ['COGS = Total Sales - Net Profit', 'COGS = Operating Expenses + Net Purchases', 'COGS = Total Assets - Total Liabilities'], 'COGS captures direct production expenses: initial inventory plus purchases and factory wages less ending inventory.'), ("What is an 'Intangible Asset'?", 'An identifiable non-monetary asset without physical substance (e.g., patents, trademarks, goodwill)', ['Physical manufacturing plant and heavy machinery', 'Cash deposited in commercial checking accounts', 'Company transport delivery trucks and vans'], 'Intangible assets derive value from intellectual, contractual, or competitive legal rights rather than physical properties.'), ("What is 'Goodwill' in corporate accounting?", 'An intangible asset recorded when a buyer acquires an existing business for more than the fair market value of net assets', ['The moral reputation of the chief executive officer', 'The charity donations made by a firm in a fiscal year', 'The annual staff holiday bonus budget'], 'Goodwill arises in acquisitions, representing unidentifiable benefits such as customer loyalty, brand prestige, and skilled labor force.'), ('What are the three core sections of a Cash Flow Statement prepared under AS 3 or Ind AS 7?', 'Operating Activities, Investing Activities, and Financing Activities', ['Trading Activities, Profit Activities, and Loss Activities', 'Asset Activities, Liability Activities, and Equity Activities', 'Sales Activities, Cost Activities, and Tax Activities'], 'A cash flow statement categorizes cash flows into core business operations, capital investments, and debt/equity capital financing.'), ('Under cash flow reporting, which activity does purchasing factory machinery fall under?', 'Investing Activities', ['Operating Activities', 'Financing Activities', 'Non-cash Supplementary Activities'], 'Acquiring or disposing of long-term property, plant, equipment, and other non-operating investments is an Investing activity.'), ('Under cash flow reporting, which activity does issuing equity shares or repaying bank loans fall under?', 'Financing Activities', ['Operating Activities', 'Investing Activities', 'Working Capital Activities'], 'Financing activities alter the size and composition of equity capital and borrowings of the corporate enterprise.'), ("What does 'EBITDA' stand for in financial earnings analysis?", 'Earnings Before Interest, Taxes, Depreciation, and Amortization', ['Equity Balance In Total Dividends and Assets', 'Economic Benchmark for Income, Tax, and Debt Allocation', 'Estimated Business Income Through Direct Audits'], 'EBITDA measures core operating profitability before the non-cash charges of depreciation/amortization and capital structure choices.'), ("What is 'Bad Debt' in trade accounts?", 'An amount owed by a debtor that is determined to be uncollectible and written off', ['A bank loan that carries high variable interest', 'A debt owed to raw material suppliers', 'A company bond downgraded by rating agencies'], 'When an account receivable cannot be recovered due to insolvency, it is expensed as bad debt.'), ("What is a 'Bank Reconciliation Statement' (BRS)?", 'A schedule explaining the difference between the bank balance per the cash book and the bank passbook', ['An application requesting a corporate business loan', 'A tax declaration submitted to the revenue commissioner', 'A list of employee direct deposit payroll payments'], 'BRS reconciles timing differences (e.g., unpresented checks, bank charges) between internal cash records and external bank statements.'), ("What is 'Capital Expenditure' (CapEx)?", 'Expenditure that results in the acquisition or enhancement of long-term assets extending beyond one year', ['Day-to-day office supply expenses and staff salaries', 'Routine vehicle fuel and maintenance costs', 'Quarterly payment of utility and telephone bills'], 'CapEx creates future economic enduring benefits and is capitalized on the balance sheet rather than expensed immediately.'), ("What is 'Revenue Expenditure' (OpEx)?", 'Routine expenses incurred for the normal day-to-day operation of a business (expensed in the current period)', ['Purchasing real estate land for a new factory', 'Building an overseas administrative headquarters', 'Acquiring a patent from a research university'], 'Revenue expenditures maintain existing earning capacity and are charged to the income statement in the current accounting period.'), ("In financial markets, what does 'IPO' stand for?", 'Initial Public Offering', ['Internal Profit Organization', 'Interbank Portfolio Option', 'Indexed Pricing Order'], 'An IPO is the first sale of commercial equity shares by a private company to the general public and institutional investors.')]
    for q, ca, wa, exp in raw_easy:
        qs.append(make_q(q, ca, wa, "EASY", exp))
    raw_med = [('What is the formula to calculate the Break-Even Point (BEP) in units?', 'BEP (units) = Fixed Costs / (Selling Price per unit - Variable Cost per unit)', ['BEP (units) = Fixed Costs / Total Sales', 'BEP (units) = Total Variable Costs / Selling Price', 'BEP (units) = Net Profit / Contribution Margin'], 'BEP is achieved when total contribution margin covers total fixed expenses, resulting in zero net operating profit or loss.'), ("What is the 'Contribution Margin per unit'?", 'Selling Price per unit minus Variable Cost per unit', ['Selling Price per unit minus Fixed Cost per unit', 'Gross Profit divided by Total Units Produced', 'Net Income divided by Total Revenue'], 'Contribution margin is the residual revenue per unit available to cover fixed overheads and generate net profit.'), ('What is the formula to calculate the Profit-Volume (P/V) Ratio?', 'P/V Ratio = (Contribution / Sales) * 100', ['P/V Ratio = (Fixed Costs / Sales) * 100', 'P/V Ratio = (Net Profit / Gross Profit) * 100', 'P/V Ratio = (Sales / Variable Costs) * 100'], 'The P/V ratio expresses the rate at which contribution is earned per dollar of sales, aiding multi-product break-even analysis.'), ("What is 'Margin of Safety' in cost-volume-profit analysis?", 'The difference between Actual Sales and Break-Even Sales', ['The cash reserve held in company savings accounts', 'The insurance coverage on warehouse factory inventory', 'The difference between Total Assets and Total Debt'], 'Margin of safety indicates the cushion of sales revenue that can be lost before the company begins incurring operating losses.'), ('Under the Diminishing Balance (Written Down Value - WDV) method, depreciation is calculated on:', 'The book value (carrying value) of the asset at the beginning of each year', ['The original historical purchase cost of the asset', 'The estimated final scrap salvage value', 'The current replacement market price'], 'WDV applies a fixed percentage to the declining book value, charging higher depreciation in earlier years.'), ('What is the formula to calculate Return on Equity (ROE)?', "ROE = Net Income / Total Shareholders' Equity", ['ROE = Operating Income / Total Assets', 'ROE = Gross Profit / Total Equity', 'ROE = EBITDA / Long-term Debt'], 'ROE measures the efficiency with which management generates profits from the capital contributed by shareholders.'), ('What is the formula to calculate the Debt-to-Equity Ratio?', "Debt-to-Equity Ratio = Total Debt / Total Shareholders' Equity", ['Debt-to-Equity Ratio = Total Assets / Total Debt', 'Debt-to-Equity Ratio = Current Liabilities / Total Equity', 'Debt-to-Equity Ratio = Interest Expense / EBIT'], 'This leverage ratio evaluates the proportion of borrowed capital relative to equity financing used to fund operations.'), ("What does the 'Interest Coverage Ratio' measure?", 'How many times operating profit (EBIT) can cover annual interest payments', ['The percentage of bank loans that carry fixed interest rates', 'The dividend yield paid to preferred shareholders', 'The ratio of cash assets to commercial paper debt'], 'Interest Coverage Ratio = EBIT / Interest Expense. A low ratio signals distress in servicing debt obligations.'), ('What is the formula to calculate Inventory Turnover Ratio?', 'Inventory Turnover Ratio = Cost of Goods Sold / Average Inventory', ['Inventory Turnover Ratio = Total Sales / Closing Inventory', 'Inventory Turnover Ratio = Average Inventory / COGS', 'Inventory Turnover Ratio = Net Purchases / Opening Inventory'], 'Inventory turnover measures how many times inventory is sold and replaced during a year; higher turnover indicates efficient sales.'), ("What does 'Days Sales Outstanding' (DSO) measure in working capital?", 'The average number of days it takes for a company to collect cash from credit sales', ['The number of days factory machines remain operational', 'The time required to manufacture finished goods from raw materials', 'The delivery transit time of shipments to retail stores'], 'DSO = (Accounts Receivable / Total Credit Sales) * 365. High DSO reflects slow customer collections and liquidity strain.'), ("What is the 'Cash Conversion Cycle' (CCC) formula?", 'CCC = Days Inventory Outstanding (DIO) + Days Sales Outstanding (DSO) - Days Payable Outstanding (DPO)', ['CCC = DIO - DSO + DPO', 'CCC = DIO + DSO + DPO', 'CCC = DSO - DIO - DPO'], 'The CCC measures the time span (in days) required to convert raw material investments into realized cash inflows from customers.'), ('What is the Economic Order Quantity (EOQ) formula?', 'EOQ = sqrt((2 * Annual Demand * Ordering Cost per order) / Annual Carrying Cost per unit)', ['EOQ = (2 * Annual Demand * Carrying Cost) / Ordering Cost', 'EOQ = sqrt((Annual Demand * Ordering Cost) / 2)', 'EOQ = (Annual Demand + Ordering Cost) / Carrying Cost'], 'EOQ determines the optimal inventory order size that minimizes the sum of inventory ordering costs and carrying holding costs.'), ('In capital budgeting, what does Net Present Value (NPV) represent?', 'The difference between the present value of cash inflows and the present value of cash outflows discounted at cost of capital', ['The total nominal accounting profit earned over the project lifespan', 'The number of years required to recover original initial outlay', 'The future value of company assets adjusted for bank interest'], 'If NPV > 0, the investment generates value exceeding the required rate of return and should be accepted.'), ("What is the 'Internal Rate of Return' (IRR)?", "The discount rate that equates the Net Present Value (NPV) of a project's cash flows to zero", ['The bank prime lending interest rate in the domestic economy', 'The minimum statutory dividend guaranteed to shareholders', 'The average annual inflation rate across project duration'], 'IRR represents the expected annualized rate of return; projects are accepted when IRR exceeds the hurdle cost of capital.'), ("What is the 'Payback Period' in capital budgeting?", 'The length of time required for cumulative project cash inflows to recover the initial investment outlay', ['The deadline for paying vendor raw material invoices', 'The maturity period of commercial long-term debentures', 'The time taken to conduct an annual financial audit'], 'Payback period measures investment liquidity and risk, though it ignores the time value of money and post-payback cash flows.'), ('What is the Weighted Average Cost of Capital (WACC)?', 'The average rate of return a company is expected to pay to all its security holders (debt and equity) weighted by proportions', ['The total interest paid to commercial commercial banks', 'The highest dividend yield recorded on the stock exchange', 'The statutory corporate tax rate levied by revenue authorities'], 'WACC serves as the universal benchmark discount rate for evaluating capital budgeting and enterprise valuation.'), ('In the Capital Asset Pricing Model (CAPM), what is the formula to calculate expected return on equity (Ke)?', 'Ke = Risk-Free Rate + Beta * (Market Return - Risk-Free Rate)', ['Ke = Risk-Free Rate * Beta + Market Return', 'Ke = (Market Return - Risk-Free Rate) / Beta', 'Ke = Risk-Free Rate + (Market Return / Beta)'], 'CAPM establishes that expected equity return equals the risk-free rate plus a risk premium proportional to systematic risk (Beta).'), ("What does a stock 'Beta' of 1.5 indicate relative to the broader market?", 'The stock is 50% more volatile than the market (higher systematic risk)', ['The stock moves exactly 50% slower than market indices', 'The stock pays a guaranteed 15% dividend yield annually', 'The company has 50% more debt than equity capital'], 'Beta measures systematic non-diversifiable risk; a Beta > 1.0 means price movements are more volatile than market swings.'), ("What is 'Unsystematic Risk' (Specific Risk) in investment finance?", 'Risk unique to an individual company or industry that can be eliminated through portfolio diversification', ['Economy-wide risk affecting all securities simultaneously', 'The risk of nationwide currency depreciation', 'The risk of war, hyperinflation, or pandemic disruptions'], 'Unsystematic risks (e.g., product recalls, labor strikes, regulatory fines) can be mitigated by holding a diversified asset basket.'), ("What does 'Operating Leverage' reflect in corporate finance?", 'The extent to which an enterprise utilizes fixed operating costs in its production structure', ['The proportion of long-term debt to equity in financing', 'The ratio of cash assets to commercial checking balances', 'The turnover rate of short-term customer receivables'], 'High fixed operating costs create high operating leverage: a small percentage change in sales causes a large swing in EBIT.'), ("What does 'Financial Leverage' reflect?", 'The degree to which a company utilizes debt (fixed financial charges) in its capital structure', ['The use of high-tech automated machinery in factories', 'The proportion of foreign sales to domestic sales', 'The speed of inventory turnover in regional retail outlets'], 'Financial leverage magnifies EPS volatility: borrowing debt at fixed rates amplifies returns to shareholders when returns exceed interest.'), ("What is the formula to calculate the 'Combined Leverage' (Total Leverage)?", 'Combined Leverage = Degree of Operating Leverage (DOL) * Degree of Financial Leverage (DFL)', ['Combined Leverage = DOL + DFL', 'Combined Leverage = DOL / DFL', 'Combined Leverage = DOL - DFL'], 'Combined leverage evaluates the total risk profile: how a percentage change in sales revenue impacts Earnings Per Share (EPS).'), ("What is 'Free Cash Flow to Firm' (FCFF)?", 'Operating cash flow generated after meeting operating expenses and capital investments, available to all capital providers', ['Cash remaining in petty cash boxes at month end', 'Total revenue minus direct variable production costs', 'Cash paid out exclusively as cash dividends to founders'], 'FCFF = EBIT * (1 - Tax Rate) + Depreciation - CapEx - Change in Working Capital, available to both debt and equity investors.'), ("What is 'Deferred Tax Liability' (DTL)?", 'Tax obligation created when accounting income is temporarily higher than taxable income (e.g., accelerated tax depreciation)', ['A tax penalty levied by the income tax appellate tribunal', 'An income tax refund due from the central treasury', 'The payroll tax deducted from employee salaries'], 'DTL represents future income taxes payable arising from temporary timing differences between books and tax regulations.'), ("What is 'Deferred Tax Asset' (DTA)?", 'A tax benefit created when taxable income exceeds accounting income temporarily, usable to reduce future taxes', ['A tax penalty due immediately upon audit notice', 'An excise duty rebate on exported consumer goods', 'A sovereign bond issued by the Ministry of Finance'], 'DTA occurs from timing items like provisions for bad debts or carried-forward business losses deductible in future tax years.'), ("What is the 'Prudence Concept' (Conservatism) in accounting?", 'Anticipate no profits, but provide for all possible losses', ['Record assets at their highest anticipated selling price', 'Record revenues as soon as contracts are verbally agreed', 'Always assume inflation will double inventory costs'], 'Prudence ensures assets and incomes are not overstated and liabilities and expenses are not understated in statements.'), ("Under the 'Cost Principle' (Historical Cost), transactions and assets are originally recorded at:", 'The actual cash or cash-equivalent purchase price paid at acquisition', ['The estimated future replacement value', 'The auction liquidation forced-sale price', 'The inflation-indexed real value'], 'Historical cost offers objective, verifiable documentation that resists speculative subjective revaluations.'), ("What is an 'Unqualified Audit Report' issued by statutory auditors?", 'A clean audit report stating financial statements present a true and fair view in conformity with accounting standards', ['A report stating financial statements are completely fraudulent', 'A report issued by auditors who lack university qualifications', 'A report indicating the company has gone bankrupt'], 'An unqualified opinion is the standard positive outcome indicating financial statements comply fully with GAAP/Ind AS.'), ("What is a 'Disclaimer of Opinion' in an auditor's report?", 'A statement where auditors declare inability to express an opinion due to severe scope limitations or missing records', ['An endorsement that the company is a safe investment', 'A legal disclaimer preventing shareholders from filing lawsuits', 'An apology for late submission of the audit report'], 'Auditors disclaim an opinion when they cannot obtain sufficient appropriate audit evidence to form a professional judgment.'), ("In standard costing, what does a 'Direct Material Price Variance' measure?", 'The difference between standard price and actual price paid multiplied by the actual quantity of materials purchased', ['The difference between standard material units and actual units used', 'The total scrap loss incurred during factory manufacturing', 'The change in supplier shipping freight charges over time'], 'Material Price Variance = Actual Quantity * (Standard Price - Actual Price); favorable if actual price is below standard.'), ("What does a 'Direct Material Usage (Quantity) Variance' measure?", 'The difference between standard quantity allowed and actual quantity used multiplied by the standard price', ['The financial discount received for bulk cash orders', 'The price inflation of raw material imports', 'The damage caused by warehouse water leaks'], 'Material Usage Variance = Standard Price * (Standard Quantity - Actual Quantity); reflects operational factory wastage.'), ('What is the primary role of the Goods and Services Tax (GST) Council in India?', 'Constitutional body (Article 279A) making recommendations on GST tax rates, exemptions, thresholds, and dispute mechanisms', ['Direct administration of central income tax returns', 'Printing sovereign paper currency notes at RBI mints', 'Fixing commercial bank repo interest rates'], 'Chaired by the Union Finance Minister and state finance ministers, the GST Council governs the federal indirect tax regime.'), ("What is 'Tax Deducted at Source' (TDS) under Indian Income Tax Act?", 'A mechanism where tax is deducted by the payer at the time of making specified payments and remitted to the government', ['A punitive fine for failing to file annual corporate returns', 'A luxury tax charged on foreign holiday flight bookings', 'A property registration levy on commercial land purchases'], 'TDS ensures regular revenue inflow and curbs tax evasion by withholding tax at the source of income generation.')]
    for q, ca, wa, exp in raw_med:
        qs.append(make_q(q, ca, wa, "MEDIUM", exp))
    raw_hard = [('According to the Modigliani-Miller Proposition I (without taxes), in a perfect capital market:', 'The market value of a firm is independent of its capital structure (debt vs equity ratio)', ['Debt financing always maximizes firm equity market value', 'Zero debt yields the lowest overall cost of capital', 'Firms must maintain a strict 50:50 debt-to-equity ratio'], 'MM Proposition I proves that enterprise value is determined by asset earning power, not by how claims are carved up.'), ('When corporate taxes are introduced into the Modigliani-Miller theorem, how does firm value change with debt?', 'Firm value increases by the present value of the interest tax shield (Value = Unlevered Value + Tax Rate * Debt)', ['Firm value remains completely unchanged', 'Firm value decreases due to legal bankruptcy threat', 'Firm value drops to zero when debt exceeds equity'], 'Interest payments are tax-deductible expenses, generating a financial tax shield that lowers WACC as leverage rises.'), ('Under the Trade-Off Theory of capital structure, the optimal capital structure is achieved where:', 'The marginal present value of the interest tax shield equals the marginal present value of financial distress costs', ['Debt reaches 100% of the total balance sheet capital', 'Cost of equity equals the risk-free rate of government bonds', 'The company operates with zero long-term borrowings'], 'Firms balance the tax benefits of debt against expected direct and indirect costs of potential insolvency/bankruptcy.'), ("What does the 'Pecking Order Theory' (Myers and Majlhaf) postulate regarding corporate financing choices?", 'Firms prioritize internal financing first, followed by low-risk debt, and issue equity shares only as a last resort', ['Firms always issue new common equity shares before taking bank debt', 'Firms borrow bank loans before utilizing retained earnings', 'Firms prefer foreign commercial borrowing over domestic credit'], 'Asymmetric information causes equity issuance to be viewed as a negative signal (overvaluation), making equity least preferred.'), ('In DuPont 3-Step Analysis, what are the three components of Return on Equity (ROE)?', 'Net Profit Margin * Asset Turnover * Equity Multiplier (Financial Leverage)', ['Gross Margin * Current Ratio * Debt Ratio', 'Operating Margin * Inventory Turnover * Return on Sales', 'EBITDA Margin * P/E Ratio * Dividend Payout'], 'DuPont decomposes ROE into operational profitability (Net Margin), asset efficiency (Turnover), and capital structure leverage.'), ("In DuPont 5-Step Analysis, what does the 'Tax Burden' component represent?", 'Net Income / EBT (Earnings Before Tax)', ['EBT / EBIT', 'EBIT / Revenue', 'Revenue / Assets'], 'The tax burden measures the proportion of pre-tax profit retained after paying taxes; a higher ratio means lower tax leakage.'), ("In DuPont 5-Step Analysis, what does the 'Interest Burden' component represent?", 'EBT / EBIT', ['Net Income / EBT', 'EBIT / Revenue', 'Assets / Equity'], 'Interest burden reflects the drag of interest expense on operating earnings; if interest is zero, the ratio equals 1.0.'), ("What does the 'Altman Z-Score' predict in financial distress analysis?", 'The statistical probability of a manufacturing company entering corporate bankruptcy within two years', ['The quarterly growth rate of company stock dividends', 'The market share captured by a new retail product', 'The optimal cash balance for treasury operations'], "Edward Altman's multivariate formula combines 5 working capital, earnings, and leverage ratios to classify solvency zones."), ('In the Black-Scholes-Merton option pricing model, which input variable is NOT directly observable in financial markets?', 'Implied Volatility of the underlying asset', ['Current stock market spot price', 'Exercise (strike) price of the contract', 'Risk-free interest rate and time to maturity'], 'Volatility must be statistically estimated from historical data or implied reversely from market option premium prices.'), ("In the Black-Scholes model, what does 'Delta' of an option represent?", 'The rate of change of option price with respect to a change in the price of the underlying asset', ['The sensitivity of option value to changes in interest rates', 'The time decay rate of an option contract per day', 'The sensitivity of option value to changes in volatility'], 'Delta ranges from 0 to 1 for calls (-1 to 0 for puts), indicating how many shares of stock replicate the option payoff.'), ("What does 'Gamma' measure in financial derivatives risk management?", "The rate of change of Delta with respect to changes in the underlying asset's price", ['The rate of change of option price with respect to time decay', 'The sensitivity of option price to shifts in implied volatility', 'The sensitivity of bond prices to changes in interest yields'], 'Gamma represents the second derivative of option price; high Gamma indicates Delta changes rapidly, requiring frequent rehedging.'), ("In bond valuation, what does 'Macaulay Duration' measure?", "The weighted average time (in years) until a bond's cash flows (coupons and principal) are received", ['The total legal lifespan until the final maturity date', 'The annual coupon payment divided by the market bond price', 'The sensitivity of bond default risk to corporate downgrades'], 'Macaulay duration measures the cash flow timeline, weighting each coupon and maturity payoff by its discounted present value.'), ("What does 'Modified Duration' measure for a fixed-income bond?", "The percentage change in a bond's price for a 100 basis point (1%) change in yield to maturity", ['The total physical years to maturity adjusted for inflation', 'The ratio of coupon rate to internal yield curve', 'The liquidity premium demanded by institutional buyers'], 'Modified Duration = Macaulay Duration / (1 + YTM/n), providing an estimate of price sensitivity to interest rate shifts.'), ("What is 'Bond Convexity' and why is it desirable for bondholders?", 'The curvature of the price-yield relationship; prices rise more when yields fall than they drop when yields rise', ['The straight-line relationship between coupon and par value', 'The guarantee that a bond will never default on payments', 'The legal right to convert debentures into equity shares'], 'Convexity improves duration approximations for large yield shifts; positive convexity is a beneficial protective feature.'), ('In corporate valuation, what is the key difference between Enterprise Value (EV) and Equity Value (Market Cap)?', 'Enterprise Value includes Market Cap plus Total Debt minus Cash; Equity Value reflects only shareholder equity', ['Enterprise Value is book value; Equity Value is market price', 'Enterprise Value excludes bank debt completely', 'Enterprise Value is calculated only for unlisted startups'], 'EV measures the total value of the operational core business, independent of capital structure financing mix.'), ('Why is the EV/EBITDA multiple considered capital structure neutral compared to the Price-to-Earnings (P/E) ratio?', 'EBITDA is calculated before interest expense and taxes, removing effects of debt leverage and differing tax rates', ['EBITDA includes preferred share dividend payouts', 'EBITDA is an audited GAAP balance sheet figure', 'P/E ratios cannot be calculated for profitable companies'], 'EV/EBITDA allows cross-firm comparisons across companies with vastly different debt-to-equity ratios and tax regimes.'), ('In capital budgeting under capital rationing, what index is used to rank projects when budget funds are strictly limited?', 'Profitability Index (PI = Present Value of Inflows / Initial Outlay)', ['Accounting Rate of Return (ARR)', 'Simple Payback Period', 'Internal Rate of Return without discounting'], 'Profitability Index identifies the projects that deliver the highest present value bang per dollar of constrained capital.'), ("What is the 'Fisher Effect' in macroeconomics and financial economics?", 'Nominal Interest Rate = Real Interest Rate + Expected Inflation Rate', ['Nominal Interest Rate = Real Interest Rate - Inflation', 'Inflation Rate = Real Growth Rate / Money Velocity', 'Exchange Rate = Ratio of Gold Reserves between nations'], 'Irving Fisher demonstrated that market nominal interest rates adjust to compensate lenders for expected loss of purchasing power.'), ('Under Purchasing Power Parity (PPP) theory, exchange rates between currencies adjust over time to:', 'Equalize the price of an identical basket of traded goods across countries', ['Match the official sovereign gold reserve holdings', 'Equalize the balance of payments deficit to zero', 'Reflect the stock market equity index movements'], 'Absolute PPP holds that a basket of goods should cost the same in all countries when measured in a common currency.'), ("In treasury management, what is 'Basis Risk' in futures hedging?", 'The risk that the price spread between the spot asset and the futures contract fluctuates unpredictably', ['The risk that the exchange clearinghouse goes bankrupt', 'The risk that commercial prime interest rates rise by 1%', 'The risk that a borrower defaults on principal payment'], 'Basis = Spot Price - Futures Price. Changes in basis prevent a futures hedge from achieving 100% perfect risk offsetting.'), ("What is 'Value at Risk' (VaR) in quantitative financial risk management?", 'The maximum expected financial loss over a specific time horizon at a given statistical confidence level (e.g., 99%)', ['The total market value of all assets held in a portfolio', 'The maximum possible loss in the worst-case historic collapse', 'The average annual return of equity mutual fund portfolios'], 'A 1-day 99% VaR of $1M means there is only a 1% probability that the portfolio will lose more than $1M in a single day.'), ("What is 'Conditional Value at Risk' (CVaR) or Expected Shortfall?", 'The expected average loss incurred given that the loss has exceeded the Value at Risk (VaR) threshold', ['The minimum profit guaranteed under standard options', 'The standard deviation of daily equity index returns', 'The maximum drawdown recorded over a ten-year cycle'], "CVaR addresses VaR's flaw by quantifying the tail risk severity when extreme catastrophic outlier events occur."), ("In cost accounting, how does 'Activity-Based Costing' (ABC) assign indirect manufacturing overheads?", "By allocating costs to specific activities and then to products based on each product's consumption of cost drivers", ['By dividing total overhead uniformly by direct labor hours', 'By applying an arbitrary 15% surcharge to direct materials', 'By expensing all manufacturing overheads immediately'], 'ABC provides precise product costings by tracing resource expenses to activities (machine setups, purchase orders, inspections).'), ('Under Ind AS 115 / IFRS 15, what is the core 5-step model for Revenue from Contracts with Customers?', 'Identify contract, identify performance obligations, determine price, allocate price, recognize revenue when satisfied', ['Draft agreement, take deposit, ship goods, bill invoice, file tax', 'Estimate costs, set margin, negotiate discount, collect cash, close', 'Audit vendor, verify credit, supply goods, record entry, report'], 'IFRS 15/Ind AS 115 establishes a universal comprehensive framework for revenue recognition across industries.'), ('Under Ind AS 116 / IFRS 16, how are operating leases recognized on the balance sheet of a lessee?', "Lessees must recognize a 'Right-of-Use Asset' (ROU) and a corresponding 'Lease Liability' for almost all leases", ['Leases are kept off-balance sheet and expensed as rent', 'Only finance leases for heavy machinery are capitalized', 'Leases are classified as contingent liabilities in notes'], 'IFRS 16 eliminated off-balance sheet operating lease treatment, bringing leased assets and obligations onto the balance sheet.'), ("What is 'Impairment of Assets' under Ind AS 36 / IAS 36?", "Recognizing an immediate loss when an asset's carrying book value exceeds its Recoverable Amount", ['The standard annual depreciation charged under SLM', 'The reduction in market value due to foreign currency swings', 'The repair cost required after factory equipment breakdown'], 'Recoverable Amount is the higher of Fair Value Less Costs to Sell and Value in Use (discounted future cash flows).'), ("In forensic accounting, what does 'Beneish M-Score' detect?", 'Statistical likelihood that a corporation has manipulated its reported accounting earnings', ['The likelihood of a hostile corporate takeover bid', 'The credit rating assigned by standard debt rating agencies', 'The tax evasion penalty owed to domestic tax authorities'], 'Messod Beneish formulated an 8-variable model analyzing accruals, gross margins, and asset quality to spot fraudulent reporting.'), ("What is 'Channel Stuffing' in deceptive revenue recognition practices?", 'Forcing distributors to accept excessive inventory before period-end to artificially inflate reported sales numbers', ['Hiding cash earnings in offshore overseas bank accounts', 'Delaying vendor invoices until the next financial year', 'Selling corporate shares secretly to company executives'], 'Channel stuffing boosts current revenue fraudulently at the expense of massive subsequent product returns or zero future orders.'), ("What is 'Cookie Jar Accounting'?", 'Creating excessive reserves in profitable years and releasing them during lean years to artificially smooth earnings', ['Diverting petty cash funds to purchase employee cafeteria snacks', 'Storing corporate secret financial ledgers in bank vaults', 'Paying corporate dividends in physical merchandise'], 'Cookie jar reserves misrepresent earnings stability, violating the principle of periodicity and matching.'), ("Under Indian Income Tax law, what is 'Minimum Alternate Tax' (MAT) levied under Section 115JB?", "A mandatory minimum tax levied on book profits of 'zero-tax' companies that declare high profits but pay low tax via deductions", ['An additional luxury surcharge on foreign imported cars', 'A flat excise duty charged on tobacco and liquor products', 'A municipal property tax on vacant corporate real estate'], 'MAT ensures profitable corporate entities contribute a baseline tax (presently 15% plus surcharge) calculated on adjusted book profits.'), ("What is the 'Arm's Length Principle' in international transfer pricing regulations?", 'Inter-company transactions between related entities must be priced as if between independent unrelated enterprises', ['Subsidiaries must operate in separate geographic territories', 'Corporate executives cannot hold shares in foreign branches', 'Bank loans must be obtained exclusively from domestic banks'], "Arm's length pricing prevents multinational corporations from shifting profits to low-tax jurisdictions via artificial intra-group prices."), ("What is 'Thin Capitalization' in international tax planning?", 'A company financed through disproportionately high debt relative to equity to exploit tax-deductible interest payments', ['A company that operates with zero working capital liquidity', 'A firm with very few corporate shareholders on its register', 'A startup operating with negative cash reserves'], 'Tax authorities enforce thin capitalization rules (e.g., Section 94B in India) capping deductible interest paid to foreign parent entities.'), ('Under the Indian Companies Act, 2013 (Section 135), what is the statutory Corporate Social Responsibility (CSR) mandate?', 'Qualifying companies must spend at least 2% of average net profits of preceding 3 financial years on approved CSR activities', ['Companies must donate 10% of gross revenue to state funds', 'Companies must hire 25% of workforce from local villages', 'All private firms must operate free primary schools'], 'Section 135 applies to firms meeting net worth, turnover, or profit thresholds, mandating 2% CSR expenditure with board oversight.')]
    for q, ca, wa, exp in raw_hard:
        qs.append(make_q(q, ca, wa, "HARD", exp))
    return qs

def get_human_resource_management_questions():
    qs = []
    raw_easy = [('What is the primary distinction between a Job Description and a Job Specification?', 'Job Description details duties and responsibilities; Job Specification details qualifications and skills required', ['Job Description sets the monthly salary; Job Specification sets the office location', 'Job Description is for contractors; Job Specification is for permanent staff', 'Job Description is created by the employee; Job Specification by the client'], 'A Job Description defines the role profile and tasks, whereas a Job Specification defines human traits, education, and competencies needed.'), ("What does 'Human Resource Planning' (HRP) primarily aim to achieve?", 'Ensuring the organization has the right number of qualified people in the right jobs at the right time', ['Eliminating all external vendor hiring permanently', 'Automating payroll deductions to zero', 'Conducting annual union strikes against management'], 'Workforce planning aligns current organizational capabilities and future business demands to forecast talent deficits or surpluses.'), ("In recruitment, what is an 'Internal Source' of candidates?", 'Promotions, internal job postings (IJP), and lateral department transfers', ['Campus recruitment drives at regional universities', 'Hiring through executive recruitment agencies', 'Posting newspaper print advertisements'], 'Internal recruitment leverages the existing talent pool, offering career mobility, faster onboarding, and lower hiring costs.'), ("What is an 'External Source' of recruitment?", 'Recruiting talent from outside the enterprise (e.g., job portals, campus hiring)', ['Promoting an existing senior associate to team lead', 'Recalling an employee from maternity leave', 'Transferring a manager from Delhi branch to Mumbai branch'], 'External hiring injects fresh perspectives, specialized technical skills, and industry practices into the organization.'), ("What does 'Onboarding' or 'Induction' refer to in employee management?", "The systematic process of integrating new hires into the organization's culture, policies, and role expectations", ['The formal exit interview conducted upon resignation', 'The disciplinary hearing preceding employee termination', 'The annual corporate salary increment review'], 'Effective onboarding accelerates time-to-productivity, lowers early turnover, and builds initial psychological engagement.'), ("What does the 'ADDIE' model stand for in instructional design and employee training?", 'Analysis, Design, Development, Implementation, and Evaluation', ['Assessment, Delegation, Delivery, Inspection, and Exit', 'Acquisition, Discipline, Direction, Incentives, and Equity', 'Action, Documentation, Diagnosis, Integration, and Examination'], 'ADDIE is the standard five-phase instructional framework used by HR and L&D teams to create effective training programs.'), ("In Kirkpatrick's four-level training evaluation model, what does Level 1 evaluate?", 'Reaction (how learners felt about and perceived the training experience)', ['Learning (the increase in knowledge or capability)', 'Behavior (the extent of applied learning on the job)', 'Results (the business impact and financial ROI)'], 'Level 1 measures participant satisfaction and perceived relevance through post-training feedback surveys.'), ("In Kirkpatrick's model, what does Level 2 evaluate?", 'Learning (the acquisition of knowledge, skills, and attitudes)', ['Reaction', 'Behavior', 'Return on Investment'], 'Level 2 tests whether participants actually mastered the concepts, often via pre- and post-training assessments.'), ("In Kirkpatrick's model, what does Level 3 evaluate?", 'Behavior (the degree to which participants apply learned skills in their daily work)', ['Reaction', 'Learning', 'Corporate brand equity'], 'Level 3 evaluates workplace behavioral transfer and operational adoption of competencies over 3 to 6 months.'), ("In Kirkpatrick's model, what does Level 4 evaluate?", 'Results (the targeted organizational outcomes such as productivity, sales, and error reduction)', ['Reaction', 'Course attendance percentages', 'Classroom snack ratings'], 'Level 4 assesses high-level business impact, comparing training outcomes against organizational bottom-line metrics.'), ("What does a '360-Degree Feedback' appraisal system incorporate?", 'Performance evaluations from superiors, peers, subordinates, and self-assessment (and sometimes customers)', ['An assessment conducted solely by the immediate direct manager', 'An automated algorithm tracking keystroke counts on keyboards', 'A quarterly inspection by the ministry of labor'], '360-degree appraisal provides a balanced, holistic evaluation of leadership, collaboration, and work behaviors.'), ("What does 'MBO' stand for in performance management?", 'Management by Objectives', ['Management by Observation', 'Monitoring Business Output', 'Measurement of Baseline Operations'], 'Pioneered by Peter Drucker, MBO aligns individual employee goals with overarching corporate strategic milestones.'), ("In performance management, what does 'BARS' stand for?", 'Behaviorally Anchored Rating Scales', ['Baseline Assessment of Realized Skills', 'Business Action and Revenue Standards', 'Behavioral Audit for Retention Strategies'], 'BARS combines qualitative critical incidents with quantitative ratings, providing concrete behavioral anchors across rating levels.'), ("What is the 'Halo Effect' in performance appraisal rating errors?", 'Allowing one outstanding positive characteristic of an employee to bias the overall appraisal favorably', ['Rating all employees strictly as average to avoid conflict', 'Rating recent performance while ignoring earlier months of work', 'Judging an employee based on their university degree alone'], 'The halo error occurs when a supervisor generalizes one strong trait (e.g., punctuality) to conclude the person excels at everything.'), ("What is the 'Horns Effect' in performance appraisal?", 'Allowing one perceived negative trait or weakness to disproportionately taint the entire evaluation', ['Giving high ratings only to employees who share personal hobbies', 'Grading employees higher than they deserve out of sympathy', 'Assuming all junior staff will fail without supervision'], "The horns effect is the inverse of the halo effect: a single flaw colors the appraiser's judgment negatively across all criteria."), ("What is the 'Recency Bias' in employee performance appraisals?", "Overemphasizing an employee's most recent actions rather than evaluating performance across the full year", ['Giving equal ratings to every team member', 'Favoring candidates who graduated from elite colleges', 'Relying exclusively on self-evaluation forms'], 'Recency error occurs when managers focus disproportionately on events from the last few weeks before review submission.'), ("What is 'Central Tendency Bias' in rating employee performance?", "A manager's tendency to rate all employees near the middle of the scale, avoiding high or low marks", ['Rating only employees working in corporate headquarters', 'Giving failing grades to the majority of workers', 'Ranking team members alphabetically'], 'Central tendency error avoids contentious extreme ratings, failing to distinguish top performers from underperformers.'), ("According to Abraham Maslow's Hierarchy of Needs, what is the most fundamental baseline tier?", 'Physiological Needs (food, water, shelter, rest)', ['Safety and Security Needs', 'Belonging and Love Needs', 'Self-Actualization Needs'], "Maslow's five tiers progress from basic biological survival necessities up to higher psychological and self-fulfillment needs."), ("According to Maslow's hierarchy, what sits at the pinnacle (highest level) of human needs?", "Self-Actualization (achieving one's full potential and personal growth)", ['Esteem Needs', 'Social Belonging Needs', 'Safety Needs'], 'Self-actualization represents the desire to maximize individual creative potential and achieve meaningful personal mastery.'), ("In Frederick Herzberg's Dual-Factor Theory, which factors prevent job dissatisfaction but do NOT motivate?", 'Hygiene Factors (salary, company policies, physical working conditions, job security)', ['Motivator Factors (achievement, recognition, responsibility, growth)', 'Intrinsic psychological drives', 'Self-actualization triggers'], 'Herzberg showed that hygiene factors merely prevent discontent; true motivation stems from intrinsic satisfiers (motivators).'), ("In Herzberg's theory, which factors genuinely drive job satisfaction, engagement, and superior performance?", 'Motivators (recognition, meaningful work, advancement, achievement, personal growth)', ['Salary, paid leaves, and parking spots', 'Office air conditioning and furniture', 'Company stationery and computer monitors'], 'Motivators fulfill higher-order psychological needs, inspiring proactive discretionary effort and commitment.'), ("In Douglas McGregor's Theory X and Theory Y, what does a 'Theory X' manager assume about employees?", 'Employees naturally dislike work, avoid responsibility, and must be closely controlled and coerced', ['Employees are intrinsically motivated and enjoy creative problem-solving', 'Employees seek self-direction and thrive under autonomy', 'Employees view work as natural as play or rest'], 'Theory X reflects an authoritarian management style emphasizing micromanagement, strict supervision, and disciplinary penalties.'), ("In Douglas McGregor's framework, what does a 'Theory Y' manager assume about employees?", 'Employees are self-directed, seek responsibility, and find work inherently natural and fulfilling', ['Employees are inherently lazy and motivated only by fear of firing', 'Employees prefer routine orders and hate making decisions', 'Employees have zero ambition and avoid working whenever possible'], 'Theory Y reflects participative leadership that empowers employees through trust, delegation, and continuous development.'), ("What does the 'POSH Act' in India mandate for workplaces with 10 or more employees?", 'Constitution of an Internal Complaints Committee (ICC) to address sexual harassment grievances', ['A mandatory 40-hour workweek cap for all executives', 'Free daily catered lunches for all staff members', 'An annual bonus equal to three months of gross salary'], 'The Sexual Harassment of Women at Workplace (Prevention, Prohibition and Redressal) Act, 2013 mandates an ICC in every workplace.'), ('Under the Payment of Gratuity Act, 1972, what is the minimum continuous service required for gratuity eligibility?', '5 years of continuous service (except in cases of death or disablement)', ['1 year of service', '3 years of service', '10 years of service'], 'An employee who renders at least 5 years of continuous service with an establishment is statutorily entitled to gratuity upon separation.'), ("Under the Employees' Provident Funds and Miscellaneous Provisions Act, 1952, what is the standard employee contribution rate?", '12% of basic wages, dearness allowance, and retaining allowance', ['8.33% of gross salary', '5% of net salary', '20% of basic pay'], 'The employee contributes 12% of basic pay and DA, matched by an equal 12% employer contribution (split into EPF and EPS).'), ("What does 'Attrition Rate' measure in human resource analytics?", 'The percentage of employees who leave an organization over a specific time period (voluntary or involuntary)', ['The speed at which new employees are promoted to management', 'The percentage of candidates who accept initial job offers', 'The number of hours employees spend in annual training'], 'Attrition Rate = (Number of Leavers / Average Number of Employees) * 100, tracking organizational talent retention health.'), ("What is an 'Exit Interview'?", 'A structured survey or conversation conducted with a departing employee to understand reasons for leaving', ['A technical interview conducted before final job offer', 'A disciplinary review before imposing salary deductions', "A celebration dinner held on an employee's work anniversary"], 'Exit interviews provide unfiltered feedback on management practices, workplace culture, compensation, and retention risks.'), ("What does 'Cost-per-Hire' (CPH) evaluate in talent acquisition?", 'The total financial investment incurred to attract, recruit, and onboard a new hire', ['The gross annual salary paid to a newly recruited candidate', 'The cost of building a dedicated office cubicle for staff', 'The fee charged by employment verification government agencies'], 'CPH aggregates internal recruiting costs and external agency/advertising expenses divided by the total number of hires.'), ("What does 'Time-to-Fill' measure in recruitment operations?", "The total number of calendar days between job requisition approval and the candidate's offer acceptance", ['The time taken by an employee to drive to work', 'The duration of the final interview panel meeting', 'The length of the probationary training program'], 'Time-to-fill monitors talent acquisition operational efficiency and capacity to meet business hiring demands promptly.'), ("What does 'ESOP' stand for in corporate compensation plans?", 'Employee Stock Ownership Plan', ['Executive Salary Overtime Package', 'Employment Standard Operating Procedure', 'Equal Share Organization Protocol'], 'ESOPs grant employees rights to purchase corporate equity shares at a predetermined strike price, aligning long-term interests.'), ("What is 'Job Enlargement' (horizontal job loading)?", "Adding more tasks of similar complexity to an employee's existing job to reduce monotony", ['Promoting an employee to executive board director', 'Increasing employee basic salary by 50%', 'Sending an employee on an overseas international transfer'], 'Job enlargement broadens the scope of activities at the same hierarchical tier to maintain interest and operational versatility.'), ("What is 'Job Enrichment' (vertical job loading)?", 'Redesigning a job to incorporate greater autonomy, decision-making responsibility, and growth opportunities', ['Increasing the number of repetitive assembly-line tasks', 'Extending mandatory overtime work hours on weekends', 'Providing free transportation and company vehicles'], 'Job enrichment empowers workers with control over task planning and execution, boosting intrinsic motivation.'), ("What is 'Moonlighting' in contemporary human resource policy?", 'Taking up secondary employment or side gigs while maintaining full-time primary employment without employer consent', ['Working exclusive night shifts at a 24-hour call center', 'Working remotely from vacation resorts', 'Volunteering for charitable causes on weekends'], 'Moonlighting raises concerns regarding conflict of interest, intellectual property leakage, fatigue, and employer policy breaches.')]
    for q, ca, wa, exp in raw_easy:
        qs.append(make_q(q, ca, wa, "EASY", exp))
    raw_med = [("What are the three core needs identified in David McClelland's Acquired Needs Theory?", 'Need for Achievement (nAch), Need for Affiliation (nAff), and Need for Power (nPow)', ['Need for Food, Need for Shelter, and Need for Water', 'Need for Salary, Need for Status, and Need for Security', 'Need for Autonomy, Need for Competence, and Need for Relatedness'], 'McClelland posited that individuals are driven by varying proportions of achievement mastery, affiliation belonging, and power influence.'), ("In Victor Vroom's Expectancy Theory of Motivation, what does 'Expectancy' represent?", "The subjective belief that one's effort will result in successful task performance (Effort -> Performance)", ['The belief that successful performance will lead to desired rewards', 'The personal value or attractiveness placed on the expected reward', 'The fear of disciplinary punishment for missing targets'], "Vroom's formula is Motivation = Expectancy * Instrumentality * Valence; if any component equals zero, motivation collapses."), ("In Vroom's Expectancy Theory, what does 'Instrumentality' represent?", 'The belief that achieving the performance standard will lead to the promised outcome or reward (Performance -> Reward)', ['The trust in organizational leadership integrity', 'The technical proficiency required to use office equipment', 'The emotional connection felt toward fellow team members'], 'Instrumentality measures the perceived reliability of the reward system: will management actually deliver the bonus if targets are met?'), ("In Vroom's Expectancy Theory, what does 'Valence' represent?", 'The positive or negative value and importance an employee places on the anticipated reward or outcome', ['The amount of physical exertion expended during the task', 'The number of hours worked per calendar week', 'The percentage of company equity owned by the worker'], 'Valence reflects personal preferences (e.g., one employee may value cash bonuses, while another prioritizes flexible hours).'), ("In J. Stacy Adams' Equity Theory, how do employees evaluate workplace fairness?", 'By comparing their ratio of outcomes (rewards) to inputs (efforts) with the outcome/input ratio of relevant referent others', ['By comparing their current pay with their highest childhood dream', 'By calculating the exact gross revenue of the enterprise', 'By checking whether their manager has a university degree'], 'Perceived inequity (under-reward or over-reward) creates psychological distress, driving behaviors to restore cognitive balance.'), ('In the 9-Box Grid talent assessment matrix, what two dimensions are plotted on the X and Y axes?', 'Performance (historical delivery) and Potential (future growth capacity)', ['Salary and Years of Tenure', 'Technical Competence and IQ Score', 'Attendance and Customer Feedback'], "The 9-box grid categorizes employees (e.g., High Potential/High Performance 'Stars') to plan succession and retention actions."), ("What is 'Succession Planning' in strategic human resource management?", 'The systematic process of identifying and developing high-potential internal candidates to fill key leadership roles', ['The immediate hiring of external agency contractors when a manager quits', 'The legal division of company assets upon corporate liquidation', 'The calculation of annual retirement pensions for union laborers'], 'Succession planning ensures leadership continuity, institutional stability, and prevents disruption when critical executives depart.'), ("In compensation management, what does 'Compa-Ratio' (Comparative Ratio) measure?", "The relationship between an employee's actual base salary and the midpoint of the salary range for that job grade", ['The ratio of male employee salaries to female employee salaries', 'The percentage of salary paid out as cash year-end bonus', 'The proportion of total company payroll to annual revenue'], 'Compa-Ratio = (Actual Salary / Salary Range Midpoint) * 100; a ratio of 100% means the employee is paid exactly at market midpoint.'), ("What is 'Broadbanding' in corporate compensation structure design?", 'Consolidating numerous narrow salary pay grades into a few wide pay bands with large salary ranges', ['Eliminating cash salaries in favor of 100% stock options', 'Paying all employees in the enterprise the identical flat rate', "Publishing everyone's monthly paychecks on public notice boards"], 'Broadbanding flattens job hierarchies, facilitates lateral transfers, and reduces bureaucratic grade-reclassification requests.'), ("In compensation management, what is 'Internal Equity'?", 'Ensuring that jobs of higher relative value within the organization receive commensurately higher pay', ['Paying higher wages than competing external market firms', 'Distributing identical bonuses regardless of individual performance', 'Paying overseas remote workers in foreign currencies'], 'Internal equity is established through systematic Job Evaluation (e.g., Point-Factor method) to establish fair internal wage hierarchies.'), ("In compensation management, what is 'External Equity'?", 'Ensuring organizational pay levels are competitive with prevailing wages paid by other employers in the industry', ['Matching executive pay to employee trade union demands', 'Equalizing wages across all global regional subsidiaries', 'Paying contractors more than permanent salaried staff'], 'External equity relies on salary benchmarking surveys to ensure the organization can attract and retain market-competitive talent.'), ('Under the Code on Wages, 2019 in India, wages must comprise what minimum percentage of the total remuneration package?', 'At least 50% of the total remuneration (allowances cannot exceed 50%)', ['At least 25%', 'At least 70%', 'At least 90%'], 'The 50% rule prevents employers from artificially depressing basic pay to minimize statutory liabilities for PF and gratuity.'), ("What is the primary objective of the 'Standing Orders' under the Industrial Employment (Standing Orders) Act, 1946?", 'Formally defining conditions of employment, disciplinary rules, attendance, and misconduct procedures for workmen', ['Fixing the daily retail selling price of manufactured goods', 'Regulating the import tariffs on foreign raw materials', 'Appointing external audit firms for financial reporting'], 'Standing orders provide clear, codified conditions of employment to minimize industrial friction and arbitrary discipline.'), ("In industrial dispute resolution, what is the role of a 'Conciliation Officer'?", 'A government official appointed to mediate negotiations between employers and unions to foster amicable settlements', ['A judge who delivers final criminal sentences to striking workers', 'A corporate consultant hired to fire unionized employees', 'A labor union president leading industrial strikes'], 'Conciliation officers assist parties in reaching mutual bilateral settlements without formal judicial litigation.'), ("What is 'Voluntary Arbitration' under Section 10A of the Industrial Disputes Act, 1947?", 'Parties mutually agree in writing to refer a dispute to an independent arbitrator whose award is binding', ['The government forcibly banning all trade union assemblies', 'The management unilaterally reducing worker wage rates', 'Workers submitting grievances to local civil police'], 'Arbitration offers a consensual, faster alternative to lengthy industrial tribunal adjudication.'), ("What is a 'Lockout' as defined in industrial relations?", 'The temporary closing of a place of employment or suspension of work by an employer during a labor dispute', ['A cessation of work by employees acting in concert', 'The permanent liquidation of an unprofitable factory', 'A government curfew imposed during public elections'], "A lockout is an employer's collective bargaining weapon, whereas a strike is the employees' collective weapon."), ("What is a 'Gherao' in Indian labor relations history?", 'A physical blockade where workers encircle managerial personnel to coerce agreement to labor demands', ['A formal written tripartite wage agreement', "An educational scholarship provided to workers' children", 'A voluntary resignation submitted by union representatives'], 'Courts in India have consistently ruled that coercive, intimidating Gherao actions are illegal and non-peaceful.'), ("What is the 'Point Method' of job evaluation?", 'A quantitative technique where jobs are evaluated and assigned points across compensable factors (skill, effort, responsibility)', ['Ranking jobs intuitively from highest paid to lowest paid', 'Classifying jobs based on the color of employee work uniforms', 'Setting salaries based on the number of daily phone calls'], 'The point-factor method breaks jobs into compensable factors with defined degree levels to calculate relative internal job worth.'), ("In human resource analytics, what does 'Employee Net Promoter Score' (eNPS) measure?", 'Employee loyalty and willingness to recommend the organization as a great place to work', ['The percentage of employees promoted within one calendar year', 'The customer satisfaction score generated by retail sales staff', 'The average annual revenue generated per employee'], "eNPS asks: 'On a scale of 0-10, how likely are you to recommend this company?' (Promoters % minus Detractors %)."), ("What is 'Human Capital ROI' (HCROI) calculated as?", '[Revenue - (Operating Expenses - Total Labor Costs)] / Total Labor Costs', ['Total Revenue / Total Number of Employees', 'Net Profit / Total Shareholder Equity', 'Total Training Budget / Number of Trained Workers'], 'HCROI calculates the return on investment generated for every dollar spent on employee compensation and benefits.'), ("In talent acquisition, what is a 'Realistic Job Preview' (RJP)?", 'Providing candidates with an honest, balanced picture of both positive and challenging aspects of the role', ['Exaggerating job benefits to convince candidates to sign offers', 'Showing candidates a glamorous promotional video of corporate retreats', 'Hiding difficult working conditions until after the probation period'], 'RJPs reduce early voluntary turnover by aligning candidate expectations with actual operational realities.'), ("What is the 'Glass Ceiling' phenomenon in organizational sociology?", 'An invisible, unacknowledged barrier that prevents qualified women and minorities from advancing to executive leadership', ['A transparent glass roof installed in modern office atriums', 'A mandatory retirement age enforced by corporate bylaws', 'A fixed salary cap imposed by government wage commissions'], 'The glass ceiling represents subtle institutional and cultural prejudices hindering demographic diversity at top ranks.'), ("What is 'Job Sharing' in flexible work arrangements?", 'Two part-time employees formally sharing the duties, hours, and pay of one full-time position', ['Two colleagues sitting at the same computer desk simultaneously', 'Rotating employees across different corporate departments weekly', "Delegating one's personal work tasks to an unpaid intern"], 'Job sharing offers work-life flexibility while preserving continuous full-time operational coverage for the role.'), ("What is 'Assessment Center' methodology in talent selection and promotion?", 'A multi-exercise evaluation where multiple assessors evaluate candidates on standardized behavioral simulations and roleplays', ['A centralized medical diagnostic clinic for pre-employment checks', 'A computer examination center for typing speed tests', 'An executive boardroom where annual bonuses are decided'], 'Assessment centers use in-basket exercises, leaderless group discussions, and case studies to gauge future competencies.'), ("In performance management, what is 'Forced Distribution' (the Bell Curve model)?", 'A system where managers are mandated to allocate employees into predetermined percentage buckets (e.g., 10% top, 70% middle, 20% bottom)', ['Giving every employee an identical 5% salary increment', 'Allowing employees to pick their own performance rating', 'Rating workers purely on the number of years served'], "Popularized by GE's Jack Welch, forced distribution aims to eliminate rating leniency but often triggers unhealthy internal competition."), ("What are 'OKRs' (Objectives and Key Results)?", 'A goal-setting framework connecting ambitious qualitative objectives with 3 to 5 measurable quantitative outcomes', ['A disciplinary procedure for terminating underperforming staff', 'An accounting calculation for payroll tax withholdings', 'An insurance policy covering workplace machinery breakdowns'], 'OKRs, popularized by Google, foster transparency, ambitious stretch goals, and rapid quarterly alignment.'), ("What does the 'Balanced Scorecard' (Kaplan & Norton) incorporate to measure performance?", 'Financial, Customer, Internal Business Processes, and Learning & Growth perspectives', ['Only historical financial earnings and balance sheet debt', 'Employee attendance records and biometric swipe logs', 'Executive stock option grants and quarterly dividend yields'], 'The balanced scorecard prevents short-term financial tunnel vision by measuring underlying operational and capability drivers.'), ("What is 'Cross-Training' in workforce capability building?", 'Training employees to perform duties outside their primary role to increase operational agility and redundancy', ['Enrolling employees in competitive athletic sports programs', 'Training employees in multiple religious traditions', 'Rotating employees between competing external firms'], 'Cross-training mitigates single-point dependency risks and allows flexible re-deployment during workload surges.'), ("What is 'Presenteeism' in workplace occupational health?", 'Employees attending work physically while unwell or disengaged, leading to sub-optimal productivity and error rates', ['Arriving at the office exactly 15 minutes before shift start', 'Submitting daily timesheets with 100% attendance records', 'Winning an award for zero sick leave taken in a year'], 'Presenteeism costs organizations more in lost output and contagious illness spread than outright legitimate absenteeism.'), ("What is 'Quiet Quitting' in contemporary workplace terminology?", "Doing only the bare minimum tasks required by one's job description, setting strict boundaries without going above and beyond", ['Resigning from a job silently without submitting an official letter', 'Working secretly for a competitor during office hours', 'Stealing confidential company client databases'], "Quiet quitting reflects disengagement where employees refuse unpaid overtime and burnout culture, rejecting 'hustle' ethos."), ("In training design, what is 'Blended Learning'?", 'An instructional model combining self-paced digital/e-learning with interactive instructor-led classroom sessions', ['Mixing employees from different departments in the same cafeteria', 'Combining payroll deductions with voluntary charitable gifts', 'Teaching technical coding alongside foreign languages'], 'Blended learning maximizes pedagogical effectiveness, leveraging digital flexibility alongside collaborative live coaching.'), ("What is 'Bona Fide Occupational Qualification' (BFOQ) in employment non-discrimination law?", 'A legitimate, necessary qualification that is reasonably essential to the normal operation of a particular business', ['A university degree issued by an accredited institution', 'A medical certificate verifying eyesight standards', 'A personal character recommendation letter from a local judge'], "BFOQ allows exemptions to discrimination rules in rare instances where a specific demographic characteristic is truly essential (e.g., hiring female guards for women's prisons)."), ('Under the Apprentices Act, 1961, what is the core legal obligation of designated establishments?', 'Providing practical workplace apprenticeship training in accordance with prescribed syllabi and paying statutory stipends', ['Guaranteeing permanent salaried employment to all apprentices', 'Paying full executive bonus packages from day one', 'Exempting apprentices from all factory safety protocols'], 'The Apprentices Act promotes skill formation, requiring industries to engage a prescribed quota of apprentices with basic stipends.')]
    for q, ca, wa, exp in raw_med:
        qs.append(make_q(q, ca, wa, "MEDIUM", exp))
    raw_hard = [('In the Ulrich HR Model, what are the four distinct strategic roles of HR professionals?', 'Strategic Partner, Administrative Expert, Employee Champion, and Change Agent', ['Recruiter, Payroll Clerk, Union Negotiator, and Disciplinary Officer', 'Executive Director, Chief Accountant, Operations Manager, and Auditor', 'Talent Hunter, Welfare Warden, Compliance Inspector, and Trainer'], "Dave Ulrich's framework aligns HR deliverables with business strategy, operational efficiency, employee needs, and organizational change."), ('Under the Code on Industrial Relations, 2020, what is the revised employee threshold for requiring prior government permission for closure or retrenchment?', '300 or more workers (increased from the previous 100 workers under the 1947 Act)', ['500 or more workers', '200 or more workers', '50 or more workers'], 'The threshold reform provides greater flexibility to medium-sized manufacturing enterprises to adjust operations without prior state sanction.'), ('Under the Code on Industrial Relations, 2020, what is the mandatory notice period required before workers can go on strike?', 'At least 14 days and not more than 60 days advance written notice for ALL industrial establishments', ['Zero notice (strikes can be called instantly)', 'Only 24 hours notice for utility providers', 'Notice is required only if the union is unregistered'], 'The 2020 Code extended strike notice mandates to all industrial sectors, eliminating sudden flash wildcat strikes.'), ("Under the Code on Social Security, 2020, how are 'Gig Workers' and 'Platform Workers' formally integrated?", 'They are legally recognized with dedicated social security schemes and a National Social Security Fund funded by aggregators', ['They are classified as permanent full-time government civil servants', 'They are declared completely exempt from all labor regulations', 'They are banned from providing services through digital platforms'], 'The 2020 Code brings gig delivery and app-based ride-hailing drivers into statutory welfare frameworks through aggregator contributions.'), ("In Hackman and Oldham's Job Characteristics Model, what are the five core job dimensions that drive critical psychological states?", 'Skill Variety, Task Identity, Task Significance, Autonomy, and Feedback', ['Salary, Benefits, Promotion Speed, Security, and Comfort', 'Education, Seniority, Punctuality, Compliance, and Loyalty', 'Team Size, Office Space, Travel Allowance, Bonuses, and Tech'], 'These five dimensions foster experienced meaningfulness, responsibility, and knowledge of results, boosting work outcomes.'), ('In the Job Characteristics Model, what is the formula to calculate the Motivating Potential Score (MPS)?', 'MPS = [(Skill Variety + Task Identity + Task Significance) / 3] * Autonomy * Feedback', ['MPS = Skill Variety * Task Identity * Task Significance * Autonomy * Feedback', 'MPS = (Skill Variety + Autonomy) * (Task Significance + Feedback)', 'MPS = (Salary + Benefits) * Promotion Likelihood'], 'Autonomy and Feedback act as multiplicative multipliers; if either is zero, overall motivating potential drops to zero.'), ("In psychometrics and employment testing, what does 'Construct Validity' evaluate?", 'The degree to which a test measures the hypothetical construct or psychological trait it purports to measure (e.g., leadership)', ['The extent to which test questions match the exact job description tasks', 'The correlation between test scores and actual future job performance ratings', 'The visual appeal and layout design of the printed exam sheets'], 'Construct validity evaluates whether a test truly captures theoretical underlying competencies like emotional intelligence or spatial logic.'), ("In employment testing, what does 'Criterion-Related Validity' measure?", 'The statistical relationship between test scores and actual job performance criteria (via predictive or concurrent studies)', ['The grammatical accuracy of the examination questions', 'The percentage of candidates who finish the exam on time', 'The legal licensing fees paid to test publishing companies'], 'Criterion validity confirms whether scoring well on the pre-hire assessment statistically predicts superior on-the-job productivity.'), ("What is the 'Adverse Impact' (Four-Fifths Rule or 80% Rule) in equal employment opportunity compliance?", 'Selection rate for a protected group is less than 80% of the selection rate for the group with the highest selection rate', ['80% of employees must receive identical annual pay bonuses', 'Women must constitute at least 80% of corporate board directors', 'No company can reject more than 20% of job applicants in a year'], 'The 80% rule serves as a mathematical screening test to flag systemic, unintended discrimination in pre-employment selection procedures.'), ("In high-volume recruitment, what does the 'Selection Ratio' represent?", 'Total Number of Hired Candidates divided by Total Number of Applicants (Hired / Applicants)', ['Total Number of Hired Candidates divided by Total Vacancies', 'Total Recruiting Costs divided by Number of Hires', 'Total Interviewers divided by Number of Candidates'], 'A low selection ratio (e.g., hiring 2 out of 100 applicants) indicates high hiring selectivity, enhancing the utility of valid test instruments.'), ("In utility analysis of employee selection, what does the 'Taylor-Russell Tables' estimate?", 'The increase in the proportion of successful employees expected from using a valid selection test over random selection', ['The cost savings achieved by outsourcing payroll processing', 'The attrition probability of senior executives based on age', 'The optimal number of vacation days to minimize sick leaves'], 'Taylor-Russell tables quantify selection test utility based on test validity, selection ratio, and base rate of success.'), ("What does the 'Brodel-Hegarty-Cronbach' utility model calculate for HR investments?", 'The net financial dollar return yielded by an employee selection program over baseline random selection', ['The tax deductions allowable for employee corporate retreats', 'The commercial real estate value of corporate office spaces', 'The legal damages payable in wrongful dismissal lawsuits'], 'Utility models quantify HR program economic benefits: Dollar Gain = N * T * r_xy * SD_y * Z_x - Cost of Testing.'), ("In strategic HRM, what does the 'Resource-Based View' (RBV) postulate regarding competitive advantage?", 'Human resources create sustainable competitive advantage if they are Valuable, Rare, Inimitable, and Non-substitutable (VRIN)', ['Competitive advantage stems solely from buying cheaper factory machinery', 'Any business model can be copied instantly by hiring external consultants', 'Physical financial capital is the only enduring competitive asset'], "Jay Barney's RBV framework demonstrates that unique human capital pools and complex organizational cultures cannot be easily copied."), ("In strategic HRM, what is the difference between 'Vertical Fit' and 'Horizontal Fit'?", 'Vertical Fit aligns HR practices with corporate business strategy; Horizontal Fit ensures internal coherence among all HR practices', ['Vertical Fit relates to salaries; Horizontal Fit relates to office layouts', 'Vertical Fit applies to junior staff; Horizontal Fit applies to executives', 'Vertical Fit is domestic compliance; Horizontal Fit is international trade'], 'High performance requires both vertical alignment with competitive positioning and horizontal synergy across recruitment, PMS, and rewards.'), ("What does 'Human Resource Accounting' (HRA) attempt to measure?", 'The economic measurement, valuation, and reporting of human capital investments and asset value to the organization', ['The calculation of monthly income tax withholdings from payroll', 'The tracking of petty cash disbursements for office lunches', "The auditing of statutory workers' provident fund bank balances"], 'HRA (using Lev & Schwartz or Flamholtz models) treats employee talent, training, and capabilities as valuable capital assets rather than pure costs.'), ("In labor economics, what does the 'Efficiency Wage Theory' explain?", 'Employers pay above-market wages because higher pay increases worker productivity, reduces turnover, and attracts top talent', ['Workers will accept below-minimum wages if free snacks are offered', 'Wage rates are determined strictly by government administrative decrees', 'Productivity decreases automatically as salaries are raised'], 'Paying above market market-clearing wages discourages shirking, cuts hiring costs, and fosters reciprocity and morale.'), ("In labor economics, what does the 'Compensating Wage Differential' account for?", 'Higher wages paid to compensate workers for undesirable, hazardous, or dangerous working conditions (e.g., offshore rigs)', ['Bonuses paid to staff who work in luxury corporate headquarters', 'Salary deductions imposed when employees take medical leaves', 'Higher wages paid to workers who hold theoretical academic degrees'], 'Compensating differentials equalize net advantage across occupations, offering hazard pay to attract workers to risky tasks.'), ("What does 'Human Resource Information System' (HRIS) integration with ERP enable?", 'Unified real-time data flows connecting core HR, payroll, talent analytics, enterprise finance, and supply chain', ["Standalone spreadsheets kept on individual managers' laptop computers", 'Manual paper ledger filing in locked basement archival rooms', 'Restricting all employee data access strictly to external auditors'], 'Enterprise HRIS integration unifies workforce planning with financial budgeting, operational capacity, and corporate performance tracking.'), ("In organizational network analysis (ONA), what is a 'Central Connector'?", 'An employee who holds a disproportionate number of informal collaborative relationships and information flows across the company', ['The main computer router located in the corporate data center', 'The receptionist stationed at the building entrance lobby', 'The chief executive officer on the official organizational chart'], 'ONA reveals informal informal influence: central connectors share knowledge widely, but can become communication bottlenecks or single-point burnout risks.'), ("In Organizational Network Analysis (ONA), what is a 'Broker' or 'Boundary Spanner'?", 'An individual who bridges structural holes between otherwise disconnected departments or silos', ['A stock trader managing the company equity investment portfolio', 'An external headhunter hired to source executive talent', 'An insurance agent selling employee group health cover'], 'Boundary spanners facilitate cross-pollination of innovative ideas and inter-departmental collaboration across organizational silos.'), ("In change management, what are the three stages of Kurt Lewin's Change Model?", 'Unfreezing, Changing (Transitioning), and Refreezing', ['Planning, Doing, and Checking', 'Initiating, Executing, and Auditing', 'Storming, Norming, and Performing'], 'Lewin showed that effective change requires breaking current inertia (Unfreezing), moving to new behaviors, and anchoring them into culture (Refreezing).'), ("In John Kotter's 8-Step Change Model, what is the critical first step?", 'Creating a sense of urgency', ['Forming a strategic vision', 'Empowering broad-based action', 'Anchoring new approaches in culture'], 'Without urgent recognition of current threats or opportunities, complacency kills change initiatives before they start.'), ("What is 'Job Embeddedness' theory in employee retention?", 'The web of organizational and community links, fit, and perceived sacrifice that keeps an employee attached to their current role', ['Embedding microchip tracking devices into employee identity cards', 'Forcing employees to sign 10-year non-compete employment bonds', 'Restricting employees from interacting with former university classmates'], 'Mitchell and Lee showed that off-the-job community roots and organizational mesh prevent turnover even when job satisfaction fluctuates.'), ("What is 'Organizational Citizenship Behavior' (OCB)?", 'Discretionary, voluntary behaviors that are not part of formal job requirements but promote effective organizational functioning', ['Voting in national parliamentary elections during work hours', 'Following basic mandatory workplace safety rules without violation', 'Filing weekly timesheets prior to the Friday afternoon deadline'], 'OCBs (altruism, conscientiousness, sportsmanship, courtesy, civic virtue) lubricate organizational machinery and foster collaborative agility.'), ("What is 'Counterproductive Work Behavior' (CWB)?", 'Intentional employee behaviors that harm the organization, its members, or legitimate business interests (e.g., theft, sabotage, bullying)', ['Making unintentional honest mathematical errors on balance sheets', 'Taking authorized medical sick leave when suffering from pneumonia', 'Asking challenging technical questions during team meetings'], 'CWBs range from interpersonal aggression and gossiping to organizational sabotage, fraud, and deliberate output restriction.'), ('In emotional intelligence (EQ) theory (Daniel Goleman), what are the five core components?', 'Self-Awareness, Self-Regulation, Motivation, Empathy, and Social Skills', ['Intellectual Quotient, Memory, Logic, Calculation, and Speed', 'Extroversion, Agreeableness, Neuroticism, Openness, and Conscientiousness', 'Power, Wealth, Dominance, Control, and Compliance'], 'Goleman demonstrated that emotional competencies correlate more strongly with executive leadership effectiveness than raw cognitive IQ.'), ("In employee relations, what is the 'Psychological Contract'?", 'The unwritten, implicit set of mutual expectations, beliefs, and obligations between an employee and their employer', ['A certified medical psychiatric clearance certificate for new hires', 'A legally binding notarized non-disclosure intellectual agreement', 'The printed employee code of conduct handbook given on day one'], 'Breaches of psychological contract (e.g., broken unwritten promises regarding career growth or fairness) destroy trust and drive rapid attrition.'), ("In labor economics, what does 'Internal Labor Market' (ILM) refer to?", 'An administrative mechanism where entry is restricted to bottom tiers and higher jobs are filled via promotion from within', ['Hiring day laborers from local street corners for cash', 'A temporary agency providing short-term secretarial coverage', 'The recruitment of foreign expatriate technical specialists'], 'Doeringer and Piore demonstrated that ILMs protect enterprise-specific skills, foster loyalty, and insulate wages from open market volatility.'), ('Under the Indian Trade Unions Act, 1926, what is the minimum number of members required to apply for registration of a trade union?', 'At least 7 members, with at least 10% or 100 workers (whichever is less) engaged in the establishment', ['At least 2 members', 'At least 50% of the entire national workforce', 'At least 500 members unconditionally'], 'The statutory threshold ensures representative collective bargaining and prevents mushrooming of frivolous microscopic unions.'), ("Under the Factories Act, 1948, a 'Welfare Officer' must be mandatorily appointed in every factory employing:", '500 or more workers', ['100 or more workers', '1,000 or more workers', '50 or more workers'], 'Section 49 mandates dedicated welfare officers to oversee canteen facilities, restrooms, crèches, and worker statutory amenities.'), ("Under the Factories Act, 1948, a 'Safety Officer' must be mandatorily appointed in every factory employing:", '1,000 or more workers (or where manufacturing processes carry severe toxic hazards)', ['250 or more workers', '100 or more workers', '50 or more workers'], 'Section 40B mandates qualified safety officers to prevent industrial accidents, inspect machinery, and enforce occupational safety.'), ("What does 'Human Resource Due Diligence' (HRDD) examine during corporate mergers and acquisitions (M&A)?", 'Evaluating leadership talent, cultural compatibility, severance liabilities, pension obligations, and key retention risks', ['Auditing physical warehouse real estate boundaries and land deeds', 'Inspecting the mechanical integrity of company transport trucks', 'Recalculating past customer sales tax receipts'], 'HRDD assesses post-merger integration risks, unrecorded labor liabilities, union friction, and talent flight that could derail merger synergies.'), ("What is 'Decoupling' in institutional theory applied to corporate HR practices?", 'Adopting formal HR policies (e.g., diversity charters) symbolically to gain legitimacy while daily operational practices remain unchanged', ['Separating the HR department into recruitment and payroll offices', 'Terminating employment contracts of underperforming managers', 'Splitting a conglomerate into two independent publicly traded firms'], 'Decoupling highlights the gap between public ceremonial policy statements and actual entrenched managerial routines on the ground.')]
    for q, ca, wa, exp in raw_hard:
        qs.append(make_q(q, ca, wa, "HARD", exp))
    return qs

def get_procurement_gem_questions():
    qs = []
    raw_easy = [("What does the acronym 'GeM' stand for in public procurement in India?", 'Government e-Marketplace', ['General Electronic Market', 'Government Enterprise Management', 'Global Electronic Mandi'], 'GeM is the national public procurement portal launched to facilitate online procurement of common goods and services.'), ('Under which Rule of the General Financial Rules (GFR), 2017 is procurement through GeM made mandatory for Government buyers?', 'Rule 149', ['Rule 144', 'Rule 153', 'Rule 161'], 'Rule 149 of GFR 2017 stipulates that procurement of goods and services available on GeM is mandatory for Ministries and Departments.'), ('What is the primary objective of establishing the Government e-Marketplace (GeM)?', 'Enhancing transparency, efficiency, inclusiveness, and speed in public procurement', ['Maximizing corporate retail profits of private shopping sites', 'Banning all private manufacturers from supplying goods', 'Operating physical retail departmental stores in state capitals'], 'GeM eliminates physical human touchpoints, prevents corruption, and enables nationwide market access for suppliers.'), ("Under GFR Rule 149(i), what is the threshold limit for 'Direct Purchase' of goods on GeM without market comparison?", 'Up to Rs 25,000 through any available GeM seller meeting quality and delivery specifications', ['Up to Rs 1,00,000', 'Up to Rs 5,00,000', 'Up to Rs 10,000'], 'Direct purchase up to Rs 25,000 allows immediate buying from any vendor meeting requisite quality, specification, and delivery period.'), ('Under GFR Rule 149(ii), what is the monetary threshold for procurement through comparison of at least three different manufacturers?', 'Above Rs 25,000 and up to Rs 5,00,000', ['Above Rs 1,00,000 and up to Rs 10,00,000', 'Above Rs 5,000 and up to Rs 50,000', 'Above Rs 5,00,000 and up to Rs 25,00,000'], 'Buyers must compare at least 3 different manufacturers/OEMs on GeM and select the lowest price (L-1) supplier.'), ('Under GFR Rule 149(iii), what procurement method is mandatory for purchases above Rs 5,00,000 on GeM?', 'Mandatory online Bidding or Reverse Auction (RA) among all eligible sellers', ['Direct spot purchase from any local shop', 'Negotiation with a single preferred vendor', 'Purchasing via physical newspaper tender coupons'], 'Purchases above Rs 5 lakh require competitive online bidding or Reverse Auction on GeM to ensure maximum market competition.'), ("What does 'L-1' designate in government tender evaluation?", 'The lowest evaluated responsive bidder among technically qualified participants', ['The first bidder who submitted their bid document online', 'The largest registered corporate supplier by annual revenue', 'The local vendor situated geographically closest to the office'], 'L-1 represents the lowest priced tender complying with all technical specifications and commercial qualification criteria.'), ('What document is generated on GeM upon physical inspection and acceptance of supplied goods by the consignee?', "CRAC (Consignee's Receipt and Acceptance Certificate)", ['EMD Receipt', 'Vendor Award Letter', 'Tender Cancellation Notice'], 'CRAC confirms that goods have arrived in good order and match specifications, triggering the mandatory payment clock.'), ('Within how many calendar days must the Consignee generate the CRAC on GeM after physical receipt of goods?', 'Within 10 days of delivery', ['Within 30 days of delivery', 'Within 45 days of delivery', 'Within 2 days of delivery'], 'GeM policy mandates CRAC generation within 10 days; if not acted upon, auto-CRAC is triggered by the system to protect sellers.'), ('After the generation of CRAC, within how many days must government buyers release payment to the seller on GeM?', 'Within 10 calendar days', ['Within 30 calendar days', 'Within 60 calendar days', 'Within 90 calendar days'], 'GeM guidelines mandate that 100% payment must be made to the seller within 10 calendar days of CRAC generation.'), ('What penal interest is charged to government buyers for delays in payments to GeM sellers beyond the mandated period?', '1% per month on the overdue payment amount', ['5% per month', '0.1% per year', 'No interest can be charged to government'], 'To enforce payment discipline and prevent MSME liquidity stress, a 1% per month penal interest is levied on delayed buyer dues.'), ("What does 'EMD' stand for in public procurement tenders?", 'Earnest Money Deposit (Bid Security)', ['Emergency Monetary Debt', 'Estimated Market Demand', 'Enterprise Milestone Delivery'], 'EMD establishes bidder seriousness and protects the buyer against frivolous bids or withdrawal during bid validity.'), ("What does 'PBG' stand for in contract management?", 'Performance Bank Guarantee (or e-PBG)', ['Public Bidding Guideline', 'Procurement Balance Grant', 'Pre-Bid Guarantee'], 'A PBG is furnished by the successful winning bidder to secure satisfactory performance and fulfillment of contract obligations.'), ('What is the typical percentage range of contract value required as Performance Security (PBG) under standard GFR rules?', '3% to 5% of the total value of the contract', ['20% to 25% of contract value', '50% of contract value', '100% of contract value'], 'Normally set between 5% and 10%, it was temporarily rationalized to 3%-5% to support vendor working capital liquidity.'), ('Under the Public Procurement Policy for MSEs Order, 2012, what mandatory annual procurement quota is reserved for Micro and Small Enterprises?', 'At least 25% of total annual purchases of goods and services by Central Ministries, Departments, and CPSEs', ['At least 10% of total annual purchases', 'At least 50% of total annual purchases', 'At least 5% of total annual purchases'], 'Central government bodies must source at least 25% of their total annual commercial procurement from eligible MSEs.'), ('Within the mandatory 25% MSE procurement target, what specific sub-target is earmarked for MSEs owned by SC/ST entrepreneurs?', '4% of total annual procurement', ['1% of procurement', '10% of procurement', '2.5% of procurement'], 'A dedicated 4% quota ensures economic empowerment and affirmative public supply chain inclusion for SC/ST enterprises.'), ('Within the mandatory 25% MSE procurement target, what specific sub-target is earmarked for MSEs owned by Women entrepreneurs?', '3% of total annual procurement', ['1% of procurement', '5% of procurement', '8% of procurement'], 'A specialized 3% sub-quota fosters female entrepreneurship by guaranteeing access to central public procurement contracts.'), ('Are registered Micro and Small Enterprises (MSEs) and recognized DPIIT Startups exempt from paying Earnest Money Deposit (EMD)?', 'Yes, they are completely exempt from EMD upon furnishing valid registration (e.g., Udyam Registration)', ['No, they must pay double the standard EMD', 'Exempt only if they operate in northeastern states', 'Exempt only for tenders below Rs 1,000'], 'To lower entry barriers, MSEs holding valid Udyam certificates and DPIIT-recognized startups are legally exempt from submitting EMD.'), ("What does 'PAC' stand for in public procurement when purchasing a specific proprietary item?", 'Proprietary Article Certificate', ['Public Audit Compliance', 'Procurement Allocation Charter', 'Pre-Authorized Contract'], "A PAC is executed under GFR Rule 166 when only one particular manufacturer's proprietary model satisfies technical requirements."), ("What is a 'Reverse Auction' (RA) on the GeM portal?", 'An online dynamic auction where qualified sellers compete in real-time by bidding downward to lower prices', ['An auction where buyers bid upward to purchase rare luxury art', 'A physical open-outcry auction conducted at district courts', 'A lottery system where winning contracts are drawn from a box'], 'During an RA, suppliers see the current lowest bid and iteratively submit lower price bids within the allotted time window.'), ("What does 'BOQ' stand for in GeM procurement bidding?", 'Bill of Quantities', ['Baseline Operating Quota', 'Buyer Order Quality', 'Bidding Overhead Question'], 'A BOQ bid allows buyers to procure multiple complex line-item goods or civil work components under a unified tender.'), ('Who is the legal governing entity that owns and operates the Government e-Marketplace?', 'GeM SPV (Special Purpose Vehicle, a Section 8 non-profit company under the Ministry of Commerce and Industry)', ['A private foreign multinational retail corporation', 'The Confederation of Indian Industry (CII)', 'A commercial consortium of private credit card banks'], 'GeM SPV is a 100% government-owned Special Purpose Vehicle set up to manage, innovate, and administer the national portal.'), ("What is an 'OEM' on the GeM portal?", 'Original Equipment Manufacturer', ['Online Enterprise Manager', 'Operating Expense Metric', 'Official Electronic Mandi'], 'OEMs are primary manufacturers or brand owners who list products and authorize distributors/resellers to quote on GeM.'), ('Can a Reseller sell products on GeM without the authorization of the Original Equipment Manufacturer (OEM)?', 'No, for categorized catalog products, valid OEM authorization is required to ensure genuine supply and warranty', ['Yes, anyone can sell any trademarked goods freely', 'Only if the reseller is a foreign company', 'Only during government holiday weekends'], 'OEM authorization protects government buyers against counterfeit items, refurbished goods, and unserviced warranty claims.'), ("What does 'NPS' stand for in public procurement tender evaluation criteria?", 'Net Present Value', ['Non-Price Score', 'National Purchase Scheme', 'New Payment System'], 'NPV compares lifecycle tender cash flows across bids involving long-term maintenance and operating costs.'), ("What is 'Liquidated Damages' (LD) in government procurement contracts?", 'Pre-agreed financial compensation deducted from seller payments for unjustified delays in delivery', ['The total legal compensation paid if a factory burns down', 'A bonus paid to vendors who deliver orders ahead of schedule', 'The customs duty charged on imported raw materials'], 'LD compensates the buyer for loss suffered due to delay, typically capped at 0.5% per week up to a maximum of 10%.'), ("Under GFR 2017, what is a 'Limited Tender Enquiry' (LTE)?", 'A procurement method where tender invitations are sent directly to a pre-qualified list of registered suppliers', ['A tender published exclusively in foreign newspapers', 'A secret bidding process conducted behind closed doors', 'A verbal telephone quotation obtained from two local shops'], 'LTE is adopted for purchases up to Rs 25 lakh or urgent requirements where open competitive advertisement is inefficient.'), ("What is an 'Advertised (Open) Tender Enquiry' under GFR 2017?", 'A public tender invitation open to all eligible bidders published on the Central Public Procurement Portal (CPPP) and GeM', ['A tender restricted strictly to government public sector undertakings', 'An informal quotation sought via WhatsApp messaging', 'A tender advertised only on local television channels'], 'Open tender ensures universal public notice, robust competition, and transparency for procurements above the LTE threshold.'), ("What is a 'Two-Bid System' (Two-Envelope System) in public tender evaluation?", 'Bidders submit Technical Bids and Financial Bids separately; financial bids are opened only for technically qualified bidders', ['Bidders must submit two identical copies of their price quote', 'Bidders must submit separate quotes for morning and evening work', 'Bidders are given two chances to re-enter their price'], 'The two-bid system prevents commercial price bias during technical evaluation, ensuring compliance before prices are revealed.'), ("What is the primary role of a 'Pre-Bid Conference' in large public tenders?", 'Clarifying tender specifications, addressing prospective bidder queries, and issuing formal amendments', ['Announcing the winning contractor before bids are opened', 'Negotiating secret financial discounts with favored vendors', 'Conducting police background checks on bidder executives'], 'Pre-bid conferences ensure technical clarity, level the playing field, and prevent post-tender disputes and bid rejections.'), ("What does 'Force Majeure' signify in public procurement contracts?", 'Unforeseeable, unavoidable catastrophic events beyond human control (e.g., war, floods, pandemics) excusing contractual delay', ['The absolute authority of the buyer to terminate contracts at will', 'The legal right of the supplier to double contract prices', 'A military takeover of private industrial factories'], 'Force Majeure relieves parties from contractual liability or liquidated damages when extraordinary events prevent performance.'), ("What is a 'Rate Contract' in public procurement?", 'An agreement with a supplier to furnish specified goods at fixed agreed rates over a designated time period', ['A contract that charges variable daily fluctuating prices', 'A shipping agreement for marine cargo container freight', 'A foreign currency hedging contract signed with the central bank'], 'Rate contracts eliminate repetitive tendering for recurring common-use items, locking in bulk-discounted prices.'), ("What does 'Golden Parameters' mean in GeM product catalog filtering?", 'The most critical core technical specifications that define the primary functionality and classification of a product', ['The decorative aesthetic colors available for office furniture', 'The luxury gold packaging required for executive deliveries', 'The maximum retail profit margin allowed to the seller'], 'Golden parameters allow automated, unbiased parametric filtering so buyers find functionally identical products across brands.'), ("What does 'CPPP' stand for in Indian public e-procurement?", 'Central Public Procurement Portal', ['Centralized Purchasing Program Plan', 'Core Private Procurement Platform', 'Commercial Public Partnership Portal'], 'CPPP (eprocure.gov.in) is the national portal mandated by the Department of Expenditure for publishing all central e-tenders.')]
